// Package essconform runs a synthesized ESS conformance suite against an implementation.
//
// Generated by `ess conform synthesize --target go`. Do not edit: change the specification and
// regenerate. The suite it runs is in suite.go beside this file.
//
// # What you write
//
// One type satisfying Target, and one test that hands it over:
//
//	func TestConformance(t *testing.T) {
//	    essconform.Run(t, func() essconform.Target { return newTarget() })
//	}
//
// Nothing else. Every scenario, every assertion and every diagnostic below is derived from the
// specification, so adding a command or an invariant to the model adds checks here without anybody
// editing a test.
//
// # The runner owns every source of variation
//
// There is no clock read, no random number and no identifier minted anywhere except in Harness,
// which the runner constructs and hands to the target in each request. A target that needs a
// correlation id or a deadline is given one. This is what makes two runs over one specification
// produce the same report on any machine, at any load, on any day.
//
// Nothing sleeps. An `eventually` step asks the target again and hands it the deadline; the waiting
// happens inside the target, which is the only layer that knows what it is waiting for. The same
// goes for a length of time a scenario claims: the runner states the length and asks Clock what it
// measured, and whether the target got there by waiting or by advancing a clock of its own is not
// something this file knows or asks.
package essconform

import (
	"bytes"
	"crypto/sha256"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"reflect"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"testing"
	"time"
	"unicode"
	"unicode/utf8"
)

// ---- exact coverage inventory and original parent admission ----------------------------------

func coverageError() error             { return fmt.Errorf("inconsistent closed coverage inventory") }
func originalDigest(raw string) string { return fmt.Sprintf("sha256:%x", sha256.Sum256([]byte(raw))) }
func sourceIdentity(value any) error {
	name, err := text(value)
	if err != nil {
		return err
	}
	for _, segment := range strings.Split(name, "/") {
		if segment == "" || segment == "." || segment == ".." {
			return coverageError()
		}
	}
	for _, r := range name {
		if r == '\\' || r == ':' || unicode.IsControl(r) {
			return coverageError()
		}
	}
	return nil
}
func suiteReference(value any) error {
	r, err := closed(value, "version digest_profile digest", "")
	if err != nil {
		return err
	}
	d, ok := r["digest"].(string)
	if r["version"] != "ess-conformance/5" || r["digest_profile"] != "sha256-json-bytes/1" ||
		!ok || !strings.HasPrefix(d, "sha256:") || !modelDigest.MatchString(strings.TrimPrefix(d, "sha256:")) {
		return coverageError()
	}
	return nil
}
func referenceFor(suite Suite) map[string]any {
	return map[string]any{"version": suite.Provenance.SuiteVersion, "digest_profile": "sha256-json-bytes/1", "digest": originalDigest(suite.original)}
}
func orderedIDs(value any) ([]string, error) {
	values, err := array(value)
	if err != nil {
		return nil, err
	}
	result := make([]string, 0, len(values))
	for _, value := range values {
		id, err := text(value)
		if err != nil {
			return nil, err
		}
		if err := scenarioIdentity(id); err != nil {
			return nil, err
		}
		if len(result) > 0 && result[len(result)-1] >= id {
			return nil, coverageError()
		}
		result = append(result, id)
	}
	return result, nil
}
func semanticKey(value any) string {
	if value == nil {
		return ""
	}
	ref := value.(map[string]any)
	kinds := []string{"domain", "type", "entity", "command", "outcome", "event", "error", "view", "actor", "transition", "binding", "component"}
	rank := 0
	for i, kind := range kinds {
		if ref["kind"] == kind {
			rank = i
			break
		}
	}
	name, ok := ref["name"].(string)
	if !ok {
		nested := ref["name"].(map[string]any)
		if ref["kind"] == "outcome" {
			name = nested["command"].(string) + "/" + nested["outcome"].(string)
		} else {
			name = nested["entity"].(string) + "/" + nested["transition"].(string)
		}
	}
	return fmt.Sprintf("%02d:%s", rank, name)
}
func checkedNeeds(value any, required bool) error {
	needs, err := array(value)
	if err != nil {
		return err
	}
	if required == (len(needs) == 0) {
		return coverageError()
	}
	previous := ""
	for _, need := range needs {
		if err := admitReference(need); err != nil {
			return err
		}
		key := semanticKey(need)
		if key <= previous {
			return coverageError()
		}
		previous = key
	}
	return nil
}
func nullableID(value any) error {
	if value == nil {
		return nil
	}
	id, err := text(value)
	if err != nil {
		return err
	}
	return scenarioIdentity(id)
}
func originIncludes(selection map[string]any, origin any) bool {
	return selection["origins"] == "generated_and_authored" || selection["origins"] == origin
}
func checkedSelection(value any, provenance map[string]any) (map[string]any, error) {
	selection, err := closed(value, "scope origins filter", "")
	if err != nil {
		return nil, err
	}
	switch selection["origins"] {
	case "generated", "authored", "generated_and_authored":
	default:
		return nil, coverageError()
	}
	scope, err := closed(selection["scope"], "kind", "component")
	if err != nil {
		return nil, err
	}
	switch scope["kind"] {
	case "system":
		if len(scope) != 1 || provenance["component"] != nil {
			return nil, coverageError()
		}
	case "component":
		name, ok := scope["component"].(string)
		if !ok || !kebabName.MatchString(name) || provenance["component"] != name {
			return nil, coverageError()
		}
	default:
		return nil, coverageError()
	}
	filter, err := closed(selection["filter"], "kind", "ids parent")
	if err != nil {
		return nil, err
	}
	switch filter["kind"] {
	case "all":
		if len(filter) != 1 {
			return nil, coverageError()
		}
	case "explicit":
		if _, err := orderedIDs(filter["ids"]); err != nil {
			return nil, err
		}
		if err := suiteReference(filter["parent"]); err != nil {
			return nil, err
		}
	default:
		return nil, coverageError()
	}
	return selection, nil
}
func checkedOutside(value any, selection map[string]any) (map[string]any, error) {
	outside, err := closed(value, "scenario origin reason needs", "")
	if err != nil {
		return nil, err
	}
	if err := nullableID(outside["scenario"]); err != nil || outside["scenario"] == nil {
		return nil, coverageError()
	}
	if outside["origin"] != "generated" && outside["origin"] != "authored" {
		return nil, coverageError()
	}
	if err := checkedNeeds(outside["needs"], outside["reason"] == "other_component"); err != nil {
		return nil, err
	}
	scope := selection["scope"].(map[string]any)
	switch outside["reason"] {
	case "other_component":
		if scope["kind"] != "component" || !originIncludes(selection, outside["origin"]) {
			return nil, coverageError()
		}
	case "origin_selection":
		if originIncludes(selection, outside["origin"]) {
			return nil, coverageError()
		}
	case "selection_filter":
		if selection["filter"].(map[string]any)["kind"] != "explicit" || !originIncludes(selection, outside["origin"]) {
			return nil, coverageError()
		}
	default:
		return nil, coverageError()
	}
	return outside, nil
}
func refusalKey(r map[string]any) []string {
	key := func(v any) string {
		if v == nil {
			return ""
		}
		return v.(string)
	}
	retainedOrigin, retainedSource := "", ""
	if r["retained"] != nil {
		retained := r["retained"].(map[string]any)
		retainedOrigin, retainedSource = key(retained["origin"]), key(retained["source"])
	}
	needs := []string{}
	for _, need := range r["needs"].([]any) {
		needs = append(needs, semanticKey(need))
	}
	return []string{key(r["origin"]), key(r["source"]), semanticKey(r["subject"]), key(r["scenario"]), key(r["code"]),
		key(r["effect"]), retainedOrigin, retainedSource, key(r["scope"]), strings.Join(needs, "\x00"), key(r["message"])}
}
func orderedRefusal(a, b map[string]any) bool {
	left, right := refusalKey(a), refusalKey(b)
	for i := range left {
		if left[i] != right[i] {
			return left[i] < right[i]
		}
	}
	return true
}
func checkedRefusal(value any, selection map[string]any, sources map[string]any, survivors map[string]string, owners map[string]string) (map[string]any, error) {
	r, err := closed(value, "origin scenario subject source code message effect retained scope needs", "")
	if err != nil {
		return nil, err
	}
	if err := nullableID(r["scenario"]); err != nil {
		return nil, err
	}
	if r["subject"] != nil {
		if err := admitReference(r["subject"]); err != nil {
			return nil, err
		}
	}
	message, ok := r["message"].(string)
	if !ok || strings.TrimSpace(message) == "" {
		return nil, coverageError()
	}
	code, ok := r["code"].(string)
	if !ok {
		return nil, coverageError()
	}
	switch r["origin"] {
	case "generated":
		if r["source"] != nil || r["subject"] == nil {
			return nil, coverageError()
		}
		number := 0
		for n := 1; n <= 14; n++ {
			if code == fmt.Sprintf("ESS-SYNTH-%03d", n) {
				number = n
			}
		}
		if number == 0 {
			return nil, coverageError()
		}
		effect := "candidate_not_emitted"
		if number == 5 || number == 11 || number == 12 || number == 14 {
			effect = "check_not_emitted"
		}
		if r["effect"] != effect {
			return nil, coverageError()
		}
	case "authored":
		if err := sourceIdentity(r["source"]); err != nil {
			return nil, err
		}
		valid := false
		for n := 1; n <= 35; n++ {
			if code == fmt.Sprintf("ESS-AUTHOR-%03d", n) {
				valid = true
			}
		}
		if !valid || r["effect"] != "candidate_not_emitted" {
			return nil, coverageError()
		}
		source, ok := sources[r["source"].(string)].(map[string]any)
		if !ok || source["disposition"] != "refused" || !reflect.DeepEqual(source["scenario"], r["scenario"]) {
			return nil, coverageError()
		}
	default:
		return nil, coverageError()
	}
	var retained any
	if id, ok := r["scenario"].(string); ok && survivors[id] != "" {
		var source any
		if owners[id] != "" {
			source = owners[id]
		}
		retained = map[string]any{"origin": survivors[id], "source": source}
	}
	if r["retained"] != nil {
		if _, err := closed(r["retained"], "origin source", ""); err != nil {
			return nil, err
		}
	}
	if !reflect.DeepEqual(retained, r["retained"]) {
		return nil, coverageError()
	}
	if err := checkedNeeds(r["needs"], r["scope"] == "outside_component"); err != nil {
		return nil, err
	}
	switch r["scope"] {
	case "in_scope":
		if !originIncludes(selection, r["origin"]) {
			return nil, coverageError()
		}
	case "outside_origin":
		if originIncludes(selection, r["origin"]) {
			return nil, coverageError()
		}
	case "outside_component":
		if selection["scope"].(map[string]any)["kind"] != "component" || !originIncludes(selection, r["origin"]) {
			return nil, coverageError()
		}
	default:
		return nil, coverageError()
	}
	return r, nil
}
func admitCoverage(root map[string]any) error {
	c, err := closed(root["coverage"], "selection knowledge generated authored outside refused authored_sources counts", "")
	if err != nil {
		return err
	}
	selection, err := checkedSelection(c["selection"], root["provenance"].(map[string]any))
	if err != nil {
		return err
	}
	if c["knowledge"] != "unknown" && c["knowledge"] != "complete_inventory" {
		return coverageError()
	}
	counts, err := closed(c["counts"], "generated authored outside refused", "")
	if err != nil {
		return err
	}
	for _, name := range []string{"generated", "authored", "outside", "refused"} {
		count, err := unsigned(counts[name])
		if err != nil {
			return err
		}
		values, err := array(c[name])
		if err != nil {
			return err
		}
		if count != uint64(len(values)) {
			return coverageError()
		}
	}
	survivors := map[string]string{}
	for _, origin := range []string{"generated", "authored"} {
		ids, err := orderedIDs(c[origin])
		if err != nil {
			return err
		}
		if len(ids) > 0 && !originIncludes(selection, origin) {
			return coverageError()
		}
		for _, id := range ids {
			if survivors[id] != "" {
				return coverageError()
			}
			survivors[id] = origin
		}
	}
	scenarios := root["scenarios"].(map[string]any)
	if len(survivors) != len(scenarios) {
		return coverageError()
	}
	for id := range scenarios {
		if survivors[id] == "" {
			return coverageError()
		}
	}
	filter := selection["filter"].(map[string]any)
	if filter["kind"] == "explicit" {
		ids, _ := orderedIDs(filter["ids"])
		if len(ids) != len(scenarios) {
			return coverageError()
		}
		for _, id := range ids {
			if _, ok := scenarios[id]; !ok {
				return coverageError()
			}
		}
	}
	previous := ""
	for _, value := range c["outside"].([]any) {
		outside, err := checkedOutside(value, selection)
		if err != nil {
			return err
		}
		id := outside["scenario"].(string)
		if id <= previous || survivors[id] != "" {
			return coverageError()
		}
		previous, survivors[id] = id, outside["origin"].(string)
	}
	sources, ok := c["authored_sources"].(map[string]any)
	if !ok {
		return coverageError()
	}
	owners := map[string]string{}
	for identity, value := range sources {
		if err := sourceIdentity(identity); err != nil {
			return err
		}
		source, err := closed(value, "digest scenario disposition", "")
		if err != nil {
			return err
		}
		digest, ok := source["digest"].(string)
		if !ok || !strings.HasPrefix(digest, "sha256:") || !modelDigest.MatchString(strings.TrimPrefix(digest, "sha256:")) {
			return coverageError()
		}
		if err := nullableID(source["scenario"]); err != nil {
			return err
		}
		switch source["disposition"] {
		case "accepted":
			id, ok := source["scenario"].(string)
			if !ok || survivors[id] != "authored" || owners[id] != "" {
				return coverageError()
			}
			owners[id] = identity
		case "refused":
		default:
			return coverageError()
		}
	}
	for id, origin := range survivors {
		if origin == "authored" && owners[id] == "" {
			return coverageError()
		}
	}
	refusedSources := map[string]bool{}
	var previousRefusal map[string]any
	for _, value := range c["refused"].([]any) {
		r, err := checkedRefusal(value, selection, sources, survivors, owners)
		if err != nil {
			return err
		}
		if previousRefusal != nil && !orderedRefusal(previousRefusal, r) {
			return coverageError()
		}
		previousRefusal = r
		if r["source"] != nil {
			refusedSources[r["source"].(string)] = true
		}
	}
	for identity, value := range sources {
		if value.(map[string]any)["disposition"] == "refused" && !refusedSources[identity] {
			return coverageError()
		}
	}
	return nil
}
func completeCoverage(c map[string]any) bool {
	if c == nil || c["knowledge"] != "complete_inventory" {
		return false
	}
	for _, value := range c["refused"].([]any) {
		if value.(map[string]any)["scope"] == "in_scope" {
			return false
		}
	}
	return true
}
func admitRunInput(raw string) (Suite, error) {
	value, err := strictJSON(raw)
	if err != nil {
		return Suite{}, err
	}
	object, ok := value.(map[string]any)
	if !ok {
		return Suite{}, coverageError()
	}
	if _, carrier := object["format"]; !carrier {
		return admitSuite(raw)
	}
	input, err := closed(value, "format suite_json parent_suites", "")
	if err != nil {
		return Suite{}, err
	}
	if input["format"] != "ess-conformance-input/1" {
		return Suite{}, coverageError()
	}
	original, err := text(input["suite_json"])
	if err != nil {
		return Suite{}, err
	}
	selected, err := admitSuiteDocument(original, true)
	if err != nil {
		return Suite{}, err
	}
	if selected.coverage == nil {
		return Suite{}, coverageError()
	}
	parents, err := array(input["parent_suites"])
	if err != nil {
		return Suite{}, err
	}
	seen := map[string]bool{originalDigest(original): true}
	child := selected
	for _, value := range parents {
		text, err := text(value)
		if err != nil {
			return Suite{}, err
		}
		parent, err := admitSuiteDocument(text, true)
		if err != nil {
			return Suite{}, err
		}
		digest := originalDigest(text)
		if seen[digest] {
			return Suite{}, coverageError()
		}
		seen[digest] = true
		if err := admitParent(child, parent); err != nil {
			return Suite{}, err
		}
		child = parent
	}
	if child.coverage["selection"].(map[string]any)["filter"].(map[string]any)["kind"] != "all" {
		return Suite{}, fmt.Errorf("missing final parent")
	}
	return selected, nil
}
func copyObject(value map[string]any) map[string]any {
	copy := map[string]any{}
	for key, value := range value {
		copy[key] = value
	}
	return copy
}
func admitParent(child, parent Suite) error {
	if parent.coverage == nil {
		return coverageError()
	}
	selection := child.coverage["selection"].(map[string]any)
	filter := selection["filter"].(map[string]any)
	if filter["kind"] != "explicit" || !reflect.DeepEqual(filter["parent"], referenceFor(parent)) {
		return coverageError()
	}
	childProvenance := copyObject(child.document["provenance"].(map[string]any))
	parentProvenance := copyObject(parent.document["provenance"].(map[string]any))
	childProvenance["component"] = childProvenance["component"]
	parentProvenance["component"] = parentProvenance["component"]
	if !reflect.DeepEqual(childProvenance, parentProvenance) {
		return coverageError()
	}
	expected := copyObject(parent.coverage)
	selected := copyObject(parent.coverage["selection"].(map[string]any))
	selected["filter"] = filter
	expected["selection"] = selected
	outside := append([]any{}, parent.coverage["outside"].([]any)...)
	for _, origin := range []string{"generated", "authored"} {
		ids := []any{}
		for _, value := range parent.coverage[origin].([]any) {
			id := value.(string)
			if _, ok := child.Scenarios[id]; ok {
				ids = append(ids, id)
			} else {
				outside = append(outside, map[string]any{"scenario": id, "origin": origin, "reason": "selection_filter", "needs": []any{}})
			}
		}
		expected[origin] = ids
	}
	sort.Slice(outside, func(i, j int) bool {
		return outside[i].(map[string]any)["scenario"].(string) < outside[j].(map[string]any)["scenario"].(string)
	})
	expected["outside"] = outside
	counts := copyObject(parent.coverage["counts"].(map[string]any))
	for _, key := range []string{"generated", "authored", "outside"} {
		counts[key] = json.Number(strconv.Itoa(len(expected[key].([]any))))
	}
	expected["counts"] = counts
	if !reflect.DeepEqual(expected, child.coverage) {
		return coverageError()
	}
	parentScenarios := parent.document["scenarios"].(map[string]any)
	for id, value := range child.document["scenarios"].(map[string]any) {
		original, ok := parentScenarios[id]
		if !ok || !reflect.DeepEqual(scenarioMeaning(value), scenarioMeaning(original)) {
			return fmt.Errorf("child changed full scenario semantics or dependencies")
		}
	}
	return nil
}

// scenarioMeaning applies only the inherited typed defaults and declared Node/predicate owners.
// Typed predicate meaning is used only after original vocabulary admission. It follows
// ess-primitives Predicate's constructors (including empty/singleton and negation defaults).
func meaningCombine(kind string, children []any) any {
	if len(children) == 0 {
		return kind == "all"
	}
	if len(children) == 1 {
		return children[0]
	}
	return []any{kind, children}
}
func meaningNot(value any) any {
	if value, ok := value.(bool); ok {
		return !value
	}
	if list, ok := value.([]any); ok && len(list) == 2 && list[0] == "not" {
		return list[1]
	}
	return []any{"not", value}
}
func meaningSequence(value any) []any {
	if value == nil {
		return []any{}
	}
	if list, ok := value.([]any); ok {
		return list
	}
	return []any{value}
}
func meaningKeys(value map[string]any) []string {
	keys := make([]string, 0, len(value))
	for key := range value {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	return keys
}

var meaningDecimal = regexp.MustCompile(`^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$`)

func meaningScalar(value any) any {
	raw, ok := value.(string)
	if !ok {
		return nodeMeaning(value)
	}
	raw = strings.TrimSpace(raw)
	if len(raw) >= 2 && (raw[0] == '\'' || raw[0] == '"') && raw[len(raw)-1] == raw[0] {
		return raw[1 : len(raw)-1]
	}
	if raw == "true" {
		return true
	}
	if raw == "false" {
		return false
	}
	if meaningDecimal.MatchString(raw) {
		if number, err := strconv.ParseFloat(raw, 64); err == nil {
			return number
		}
	}
	return raw
}
func meaningOperand(value any) any {
	if raw, ok := value.(string); ok {
		raw = strings.TrimSpace(raw)
		if strings.Contains(raw, ".") && factPath.MatchString(raw) {
			if _, err := strconv.ParseFloat(raw, 64); err != nil {
				return []any{"fact", raw}
			}
		}
	}
	return []any{"literal", meaningScalar(value)}
}

var meaningOperators = map[string]string{
	"eq": "==", "equals": "==", "==": "==", "ne": "!=", "not_equals": "!=", "!=": "!=",
	"lt": "<", "<": "<", "le": "<=", "lte": "<=", "<=": "<=", "gt": ">", ">": ">",
	"ge": ">=", "gte": ">=", ">=": ">=",
}

func meaningLeaf(raw string) any {
	raw = strings.TrimSpace(raw)
	switch raw {
	case "true", "always":
		return true
	case "false", "never":
		return false
	}
	if tail, ok := strings.CutPrefix(raw, "not "); ok {
		return meaningNot(meaningLeaf(tail))
	}
	for _, function := range []string{"defined", "exists", "missing"} {
		if tail, ok := strings.CutPrefix(raw, function); ok {
			tail = strings.TrimSpace(tail)
			if strings.HasPrefix(tail, "(") && strings.HasSuffix(tail, ")") {
				value := []any{"defined", strings.TrimSpace(tail[1 : len(tail)-1])}
				if function == "missing" {
					return meaningNot(value)
				}
				return value
			}
		}
	}
	var quote byte
	for i := 0; i < len(raw); i++ {
		char := raw[i]
		if quote != 0 {
			if char == quote {
				quote = 0
			}
			continue
		}
		if char == '\'' || char == '"' {
			quote = char
			continue
		}
		op := ""
		if i+1 < len(raw) {
			switch raw[i : i+2] {
			case "==", "!=", "<=", ">=":
				op = raw[i : i+2]
			}
		}
		if op == "" && (char == '<' || char == '>') {
			op = string(char)
		}
		if op != "" {
			return []any{"compare", strings.TrimSpace(raw[:i]), op, meaningOperand(raw[i+len(op):])}
		}
	}
	return []any{"truthy", raw}
}
func predicateMeaning(value any) any {
	switch value := value.(type) {
	case bool:
		return value
	case string:
		return meaningLeaf(value)
	case []any:
		children := make([]any, 0, len(value))
		for _, item := range value {
			children = append(children, predicateMeaning(item))
		}
		return meaningCombine("all", children)
	case map[string]any:
		children := make([]any, 0, len(value))
		for _, key := range meaningKeys(value) {
			children = append(children, meaningEntry(key, value[key]))
		}
		return meaningCombine("all", children)
	default:
		panic("predicate meaning requires prior typed admission")
	}
}
func meaningEntry(key string, value any) any {
	switch key {
	case "all", "and", "all_of", "any", "or", "none", "none_of_these":
		children := []any{}
		for _, item := range meaningSequence(value) {
			children = append(children, predicateMeaning(item))
		}
		kind := "any"
		if key == "all" || key == "and" || key == "all_of" {
			kind = "all"
		}
		result := meaningCombine(kind, children)
		if key == "none" || key == "none_of_these" {
			return meaningNot(result)
		}
		return result
	case "not":
		return meaningNot(predicateMeaning(value))
	case "forall", "exists":
		body := value.(map[string]any)
		return []any{key, body["in"], body["as"], predicateMeaning(body["that"])}
	}
	if list, ok := value.([]any); ok {
		items := make([]any, 0, len(list))
		for _, item := range list {
			items = append(items, meaningScalar(item))
		}
		return []any{"any_of", key, items}
	}
	if mapping, ok := value.(map[string]any); ok {
		children := make([]any, 0, len(mapping))
		for _, operator := range meaningKeys(mapping) {
			children = append(children, meaningOperator(key, operator, mapping[operator]))
		}
		return meaningCombine("all", children)
	}
	return []any{"compare", key, "==", []any{"literal", meaningScalar(value)}}
}
func meaningOperator(path, operator string, value any) any {
	if op, ok := meaningOperators[operator]; ok {
		return []any{"compare", path, op, meaningOperand(value)}
	}
	switch operator {
	case "defined", "exists":
		result := []any{"defined", path}
		if !value.(bool) {
			return meaningNot(result)
		}
		return result
	case "truthy":
		return []any{"truthy", path}
	default:
		kind := "any_of"
		if operator == "none_of" || operator == "not_in" {
			kind = "none_of"
		}
		items := []any{}
		for _, item := range meaningSequence(value) {
			items = append(items, meaningScalar(item))
		}
		return []any{kind, path, items}
	}
}
func rankingMeaning(value any) any {
	keys := []any{}
	for _, item := range value.([]any) {
		words := strings.Fields(item.(string))
		direction := "asc"
		if len(words) == 2 && (words[1] == "desc" || words[1] == "descending") {
			direction = "desc"
		}
		keys = append(keys, []any{words[0], direction})
	}
	return keys
}

// Integer metadata and original source strings never pass through this semantic comparison.
func scenarioMeaning(value any) any {
	scenario := copyObject(value.(map[string]any))
	source := map[string]bool{}
	for _, ref := range scenario["source"].([]any) {
		source[semanticKey(ref)] = true
	}
	scenario["source"] = source
	steps := []any{}
	for _, value := range scenario["steps"].([]any) {
		step := copyObject(value.(map[string]any))
		defaults := map[string]string{
			"execute_command": "input", "expect_error": "fields", "expect_event": "payload shape",
			"query_view": "params", "eventually_view": "params", "eventually_event": "payload shape",
			"expect_invocation": "input", "expect_duration": "", "expect_halt": "params", "eventually_halt": "params",
		}
		for _, key := range strings.Fields(defaults[step["step"].(string)]) {
			if _, ok := step[key]; !ok {
				step[key] = map[string]any{}
			}
		}
		if step["step"] == "execute_command" {
			if _, ok := step["actor"]; !ok {
				step["actor"] = nil
			}
		}
		for _, key := range []string{"input", "params"} {
			if values, ok := step[key].(map[string]any); ok {
				step[key] = valuesMeaning(values)
			}
		}
		for _, key := range []string{"payload", "fields"} {
			if values, ok := step[key]; ok {
				step[key] = nodeMeaning(values)
			}
		}
		if shape, ok := step["shape"].(map[string]any); ok {
			shapes := map[string]any{}
			for key, value := range shape {
				leaf := copyObject(value.(map[string]any))
				if _, ok := leaf["optional"]; !ok {
					leaf["optional"] = false
				}
				shapes[key] = leaf
			}
			step["shape"] = shapes
		}
		if expectation, ok := step["expectation"].(map[string]any); ok {
			expected := copyObject(expectation)
			switch expected["expect"] {
			case "contains", "absent", "at":
				if _, ok := expected["fields"]; !ok {
					expected["fields"] = map[string]any{}
				}
			case "counts":
				if _, ok := expected["at_least"]; !ok {
					expected["at_least"] = nil
				}
				if _, ok := expected["at_most"]; !ok {
					expected["at_most"] = nil
				}
			}
			if fields, ok := expected["fields"].(map[string]any); ok {
				expected["fields"] = valuesMeaning(fields)
			}
			if predicate, ok := expected["predicate"]; ok {
				expected["predicate"] = predicateMeaning(predicate)
			}
			if ranking, ok := expected["order_by"]; ok {
				expected["order_by"] = rankingMeaning(ranking)
			}
			step["expectation"] = expected
		}
		steps = append(steps, step)
	}
	scenario["steps"] = steps
	return scenario
}
func valuesMeaning(values map[string]any) any {
	result := map[string]any{}
	for name, value := range values {
		field := copyObject(value.(map[string]any))
		if field["kind"] == "literal" {
			field["value"] = nodeMeaning(field["value"])
		}
		result[name] = field
	}
	return result
}
func nodeMeaning(value any) any {
	switch value := value.(type) {
	case json.Number:
		number, _ := value.Float64()
		return number
	case []any:
		result := make([]any, 0, len(value))
		for _, element := range value {
			result = append(result, nodeMeaning(element))
		}
		return result
	case map[string]any:
		result := map[string]any{}
		for key, element := range value {
			result[key] = nodeMeaning(element)
		}
		return result
	default:
		return value
	}
}

// ---- what an implementation offers ------------------------------------------------------------

// Node is one specification value: nil, bool, float64, string, []Node or map[string]Node.
//
// Deliberately not `any` with a comment: these six are what the model's types project to, and a
// target returning anything else has returned something the specification cannot describe.
type Node = any

// Row is one row of a view: a value per projected field name.
type Row = map[string]Node

// Target is an implementation a conformance suite can be run against.
//
// Every method answers a question some ESS construct asks. There is no assertion among them and no
// reset beyond the isolation ScenarioContext requires: a target reports what it observed, and the
// runner decides whether the specification is satisfied. A method that answered a question the
// suite is supposed to ask would make the suite ask the implementation for its own verdict.
type Target interface {
	// Identity names the implementation under test, for the report.
	Identity() (Identity, error)

	// BeginScenario and EndScenario bracket each scenario. Observations from one scenario may not
	// satisfy another, and this is where a target makes that true.
	BeginScenario(scenario ScenarioContext) error
	EndScenario(scenario ScenarioContext) error

	// ExecuteCommand invokes one command and reports the branch it took, the error it declared and
	// the events it emitted directly.
	//
	// Return ErrUnsupported where the implementation offers no way to invoke it — a command whose
	// actor is the implementation itself has no caller a target can be. The scenario is reported
	// as skipped, which is a different fact from the command being wrong.
	ExecuteCommand(request CommandRequest) (CommandResult, error)

	// QueryView reads one view at the consistency the request demands. A read_your_writes view must
	// show the command that just returned, and the target blocks until it can.
	QueryView(request ViewRequest) (ViewResult, error)

	// ObserveEvents reports the events seen for this activity, away from the command that caused
	// them, until the deadline.
	ObserveEvents(request EventObservationRequest) ([]ObservedEvent, error)

	// ConfigureExternalOutcome forces an outcome declared `external:` to take a named branch.
	ConfigureExternalOutcome(control ExternalOutcomeControl) error

	// RedeliverEvent delivers an event a second time. The only way to perform the claim
	// `delivery: at_least_once` makes.
	RedeliverEvent(request RedeliveryRequest) error

	// ObserveInvocations reports the commands one binding invoked and what it passed.
	//
	// Return ErrUnsupported where the implementation cannot expose this; the scenario is reported
	// as unsupported rather than failed, which is a different fact.
	ObserveInvocations(request InvocationObservationRequest) ([]Invocation, error)
}

// ErrUnsupported is what a target returns for a semantic it cannot expose.
//
// Distinct from a failure: a suite that counted "the implementation cannot show me this" as "the
// implementation is wrong" would report a defect nobody can fix.
var ErrUnsupported = errors.New("the target does not expose this")

// Identity names the implementation under test.
type Identity struct {
	Name    string
	Version string
}

// ScenarioContext is what a target is told about the scenario it is bracketing.
type ScenarioContext struct {
	// Scenario is the scenario id, as the suite writes it.
	Scenario string
	// Correlation is this run's activity id, minted by the runner.
	Correlation string
}

// CommandRequest is one command invocation.
type CommandRequest struct {
	Command     string
	Actor       string
	Input       map[string]Node
	Correlation string
}

// CommandResult is what one command did.
type CommandResult struct {
	// Outcome is the branch it took, empty when it refused.
	Outcome string
	// Error is the declared error it refused with, empty when it did not.
	Error string
	// Consistency is a token a later read_your_writes query may demand, empty when the target has
	// no such token.
	Consistency string
	// DirectEvents are the events emitted as part of the command returning.
	DirectEvents []ObservedEvent
}

// ObservedEvent is one event and what it carried.
type ObservedEvent struct {
	Event   string
	Payload map[string]Node
}

// EventObservationRequest asks for the events of one activity.
type EventObservationRequest struct {
	Event       string
	Correlation string
	Deadline    Deadline
}

// RedeliveryRequest asks for one event to be delivered again.
type RedeliveryRequest struct {
	Event       string
	Correlation string
}

// ViewRequest reads one view.
type ViewRequest struct {
	View string
	// Params is the value bound to each parameter the view declares, resolved.
	//
	// Empty for a view with no `params:`, which is most of them. A view that declares them is one
	// the implementation cannot answer without them — ACD's position in a queue is per queue — and
	// the runner refuses to send a request with a parameter it could not resolve rather than
	// reading a different set of rows and asserting against those.
	Params map[string]Node
	// AtLeast is the consistency token the read must reflect, empty for a current read.
	AtLeast     string
	Correlation string
	Deadline    Deadline
}

// ViewResult is what a view holds.
type ViewResult struct {
	Rows []Row
}

// InvocationObservationRequest asks what one binding invoked.
type InvocationObservationRequest struct {
	Binding     string
	Command     string
	Correlation string
	Deadline    Deadline
}

// Invocation is one command a binding invoked, and what it passed.
type Invocation struct {
	Command string
	Input   map[string]Node
}

// ExternalOutcomeControl forces an external outcome to a branch.
type ExternalOutcomeControl struct {
	Command     string
	Outcome     string
	Correlation string
}

// Clock is what a target offers so that a scenario can claim a length of time.
//
// Optional, and separate from Target on purpose. A duration claim is a claim about a system's own
// timers — a wrap-up window, a TTL, a queue-exit threshold — and plenty of implementations have
// none worth testing. Folding these two methods into Target would break every target that already
// compiles, to no benefit; leaving them out of the suite would leave the claims unwritable. So a
// target that has a clock implements this, and one that does not is *skipped* on the scenarios that
// need it. Never passed: a window nobody held is not a window that held.
//
//	func (t *target) MarkInstant(mark InstantMark) error {
//	    t.marks[mark.Instant] = t.now()
//	    return nil
//	}
//
//	func (t *target) ObserveElapsed(request ElapsedRequest) (ElapsedObservation, error) {
//	    opened, ok := t.marks[request.Instant]
//	    if !ok {
//	        return ElapsedObservation{}, fmt.Errorf("`%s` was never marked", request.Instant)
//	    }
//	    t.advance(opened.Add(time.Duration(request.Hold) * time.Second))
//	    return ElapsedObservation{
//	        ElapsedMillis: t.now().Sub(opened).Milliseconds(),
//	        Published:     t.publishedSince(request.Watching, opened),
//	    }, nil
//	}
//
// How the target gets there is its own business. A target driving a real system waits; a target
// with a clock of its own advances it and answers immediately. Both answer the same question, and
// the runner compares the answer with what the suite claimed.
type Clock interface {
	// MarkInstant records the instant this scenario has reached, under a name a later claim
	// measures from.
	MarkInstant(mark InstantMark) error

	// ObserveElapsed lets a window close and reports what the clock read, and what was published
	// while it was open.
	//
	// It reports an observation and never a verdict: whether the reading satisfies the claim is
	// the runner's decision, made against the suite.
	ObserveElapsed(request ElapsedRequest) (ElapsedObservation, error)
}

// OrderedReader is what a target offers so that a scenario can claim a consumer stopped a scan.
//
// Optional, and separate from Target for the reason Clock is: plenty of implementations read a view
// by materialising it, and folding this into Target would break every target that already compiles.
// A target that can read a listing a row at a time implements this; one that cannot is *skipped* on
// the scenarios that need it. Never passed: a scan nobody stopped is not a scan that halted.
//
//	func (t *target) ScanView(request ScanRequest) (ScanObservation, error) {
//	    produced, halted := 0, false
//	    t.listing(request.View).ScanOrdered(func(row Row) bool {
//	        produced++
//	        if produced >= request.StopAfter {
//	            halted = true
//	            return false
//	        }
//	        return true
//	    })
//	    return ScanObservation{Produced: produced, Halted: halted}, nil
//	}
//
// Produced is the *source's* count and not the reader's. A target that reports how many rows it
// handed on answers StopAfter whatever it did, which makes every implementation halt and the claim
// mean nothing. A target whose only ordered read returns a slice answers len(slice) and false, which
// is a red scenario and is the finding.
type OrderedReader interface {
	// ScanView reads a view in its declared order, hands rows to a reader that takes StopAfter of
	// them and then says stop, and reports what the iteration did.
	//
	// It reports an observation and never a verdict: whether that is the halt the scenario claimed
	// is the runner's decision, made against the suite.
	ScanView(request ScanRequest) (ScanObservation, error)
}

// ScanRequest asks for a bounded ordered read of one view.
type ScanRequest struct {
	// View is the view to read, in the order it declares.
	View string
	// Params is what the caller supplies for a view that declares `params:`, resolved.
	Params map[string]Node
	// StopAfter is how many rows the reader takes before it says stop. Never zero.
	StopAfter int
	// AtLeast is the consistency token a read_your_writes read demands, empty when there is none.
	AtLeast     string
	Correlation string
	Deadline    Deadline
}

// ScanObservation is what one ordered read did, as the target that performed it saw it.
type ScanObservation struct {
	// Produced is how many rows the ordered source yielded before the read ended.
	Produced int
	// Halted says whether the read ended because the reader said stop, rather than because the
	// source ran out. Both facts are needed: a source holding exactly StopAfter rows produces
	// StopAfter either way.
	Halted bool
}

// InstantMark names the instant a scenario has reached.
type InstantMark struct {
	Instant     string
	Correlation string
}

// ElapsedRequest asks how much of a window has closed, and what happened in it.
type ElapsedRequest struct {
	// Instant is the name of the instant the window opens at, marked earlier in this scenario.
	Instant string
	// Hold is how many seconds of the window to let close before answering. Zero asks for the
	// reading as it stands, which is what a `within` claim wants.
	Hold int
	// Watching is the event whose publication inside the window the runner is asking about, empty
	// when there is none.
	Watching    string
	Correlation string
}

// ElapsedObservation is what a clock read, and what it saw.
type ElapsedObservation struct {
	// ElapsedMillis is how much has passed since the marked instant, on the target's own clock.
	ElapsedMillis int64
	// Published is how many times the watched event was published inside the window.
	Published int
}

// Deadline is when the target may stop waiting, on the runner's clock.
//
// A budget rather than an instant, and there is no poll interval: a poll interval is a fixed delay
// spelled as configuration, which is the same test of the machine it runs on repeated in a loop.
type Deadline struct {
	// Attempts is how many more times the runner will ask.
	Attempts int
}

// ---- the harness ------------------------------------------------------------------------------

// Harness owns every source of variation: the ids handed to a target, and how many times an
// `eventually` step asks before giving up.
//
// Constructed per run, so "the same runner produces the same report" is not a discipline anybody
// has to keep — two identically-constructed harnesses cannot diverge.
type Harness struct {
	system   string
	sequence int
	attempts int
}

// NewHarness returns the harness a run uses, seeded from the specification's own system name.
func NewHarness(system string) *Harness {
	return &Harness{system: reduce(system), attempts: 8}
}

// Correlation mints the next activity id.
func (h *Harness) Correlation() string {
	h.sequence++
	return fmt.Sprintf("%s-%06d", h.system, h.sequence)
}

// Deadline is the budget an `eventually` step is given.
func (h *Harness) Deadline() Deadline {
	return Deadline{Attempts: h.attempts}
}

// reduce turns a system name into something usable as an identifier segment.
func reduce(system string) string {
	var parts []string
	for _, word := range strings.FieldsFunc(system, func(r rune) bool {
		return !(r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9')
	}) {
		parts = append(parts, word)
	}
	if len(parts) == 0 {
		return "ess"
	}
	return strings.Join(parts, "-")
}

// ---- the suite --------------------------------------------------------------------------------

// Suite is a synthesized conformance suite.
type Suite struct {
	Provenance Provenance          `json:"provenance"`
	Scenarios  map[string]Scenario `json:"scenarios"`
	original   string
	document   map[string]any
	coverage   map[string]any
}

// Provenance says which specification this suite came from.
//
// SpecDigest is the field that makes a passing run worth anything: without it a report says that
// some implementation passed some suite.
type Provenance struct {
	SuiteVersion         string `json:"suite_version"`
	System               string `json:"system"`
	SpecificationVersion string `json:"specification_version"`
	SpecDigest           string `json:"spec_digest"`
	ContractDigest       string `json:"contract_digest"`
}

// Scenario is one thing the specification obliges an implementation to do.
type Scenario struct {
	Purpose string `json:"purpose"`
	Steps   []Step `json:"steps"`
}

// Step is one step of a scenario. Which fields are set depends on Step.
type Step struct {
	Step    string           `json:"step"`
	Command string           `json:"command,omitempty"`
	Actor   string           `json:"actor,omitempty"`
	Input   map[string]Value `json:"input,omitempty"`
	Outcome *OutcomeRef      `json:"outcome,omitempty"`
	Force   *OutcomeRef      `json:"force,omitempty"`
	Event   string           `json:"event,omitempty"`
	// Payload is plain values, not Value: an event's fields are compared against what the
	// specification declared them to be, and there is nothing earlier in the scenario for them to
	// refer to. `input` and a view expectation's `fields` are the ones that can refer back.
	Payload map[string]Node `json:"payload,omitempty"`
	Shape   map[string]Held `json:"shape,omitempty"`
	Error   string          `json:"error,omitempty"`
	View    string          `json:"view,omitempty"`
	// Params is what the caller supplies for a view that declares `params:`. Value, not Node, for
	// the same reason `input` is: a parameter may be the identity an earlier step captured, which
	// the suite cannot know and names instead.
	Params      map[string]Value `json:"params,omitempty"`
	Expectation *Expectation     `json:"expectation,omitempty"`
	Binding     string           `json:"binding,omitempty"`
	Instance    string           `json:"instance,omitempty"`
	Entity      string           `json:"entity,omitempty"`
	Field       string           `json:"field,omitempty"`
	// Instant is the window's anchor: the name a `mark_instant` step gave one instant of this
	// scenario. Never inferred from the step before it — a window whose start moves when something
	// is inserted above it is the defect these four steps were added to fix.
	Instant string `json:"instant,omitempty"`
	// Elapsed is a length of time in whole seconds.
	Elapsed int `json:"elapsed,omitempty"`
	// After is how many rows a reader takes from an ordered view before it says stop.
	//
	// Never zero in a suite this runner will see: the authored format refuses a halt claimed after
	// no rows at all, because a reader that takes none never sees one and so never says stop.
	After int `json:"after,omitempty"`
}

// Held is what one declared payload field must hold.
//
// Separate from a value match because the two are different kinds of claim, and only one of them is
// free: a value is assertable only where some construct says where it comes from, and a type is
// declared outright.
type Held struct {
	Holds string `json:"holds"`
	Kind  string `json:"kind,omitempty"`
}

// OutcomeRef names one branch of one command.
type OutcomeRef struct {
	Command string `json:"command"`
	Outcome string `json:"outcome"`
}

// Value is one value a step carries: written down, captured earlier, or read from an event.
type Value struct {
	Kind     string `json:"kind"`
	Value    Node   `json:"value,omitempty"`
	Instance string `json:"instance,omitempty"`
	Event    string `json:"event,omitempty"`
	Field    string `json:"field,omitempty"`
}

// Expectation is what must hold of a view.
//
// AtLeast and AtMost are pointers because absent and zero are different answers: a floor of zero
// requires nothing, and a suite that wrote neither bound is asking nothing at all — which is a
// generator defect this runner reports rather than passes.
type Expectation struct {
	Expect    string           `json:"expect"`
	Fields    map[string]Value `json:"fields,omitempty"`
	Predicate json.RawMessage  `json:"predicate,omitempty"`
	OrderBy   []string         `json:"order_by,omitempty"`
	AtLeast   *int             `json:"at_least,omitempty"`
	AtMost    *int             `json:"at_most,omitempty"`
	Position  *Position        `json:"position,omitempty"`
}

// Position is which row of a view an assertion is about.
//
// `last` is not `nth` at any number a suite could write, because the count is the target's — which
// is why the three cases are three and not one with an index.
type Position struct {
	Row   string `json:"row"`
	Index int    `json:"index,omitempty"`
}

// ---- running ----------------------------------------------------------------------------------

// Run executes every scenario of the embedded suite against a freshly built target.
//
// One target per scenario, because scenario isolation is the suite's own requirement and a shared
// target makes it the adopter's discipline instead.
func Run(t *testing.T, newTarget func() Target) {
	t.Helper()

	config, err := reportConfiguration()
	if err != nil {
		t.Fatalf("report configuration: %v", err)
	}
	suite, err := admitRunInput(suiteJSON)
	if err != nil {
		t.Fatalf("suite admission: %v", err)
	}
	if suite.coverage != nil && config.version != "2" {
		t.Fatalf("suite/5 requires explicit ESS_REPORT_FORMAT=2 before execution")
	}
	suite, err = executionSuite(suite)
	if err != nil {
		t.Fatalf("suite execution adaptation: %v", err)
	}

	// Sorted, so the order scenarios run in is the order they are written in the report, on every
	// machine. Go randomises map iteration on purpose and a suite that reported in that order would
	// be unreadable across two runs.
	ids := make([]string, 0, len(suite.Scenarios))
	for id := range suite.Scenarios {
		ids = append(ids, id)
	}
	sort.Strings(ids)

	t.Logf(
		"%s %s, %d scenario(s), spec digest %s",
		suite.Provenance.System,
		suite.Provenance.SpecificationVersion,
		len(ids),
		suite.Provenance.SpecDigest,
	)

	// One extra target, for the name the report carries. Asked before any scenario runs so a
	// target that cannot name itself fails the run here, with that message, rather than leaving a
	// report that says nothing about what was tested.
	identity, err := newTarget().Identity()
	if err != nil {
		t.Fatalf("the target does not name itself: %v", err)
	}

	harness := NewHarness(suite.Provenance.System)
	results := make([]scenarioResult, 0, len(ids))
	for _, id := range ids {
		scenario := suite.Scenarios[id]
		// Read after the subtest, not returned from it: Skipf and Fatalf leave through Goexit,
		// and what the run had decided by then is the only record of how it left.
		status := statusPassed
		terminal := false
		t.Run(id, func(t *testing.T) {
			run := &run{
				t:           t,
				target:      newTarget(),
				harness:     harness,
				correlation: harness.Correlation(),
				instances:   map[string]Node{},
				marked:      map[string]bool{},
				observed:    map[string][]ObservedEvent{},
				status:      statusPassed,
			}
			returned := false
			defer func() {
				status = run.status
				terminal = run.callbacksComplete && (returned || status != statusPassed)
				if config.version == "2" && t.Failed() {
					status = statusFailed
				}
			}()
			run.execute(id, scenario)
			returned = true
		})
		if config.version == "1" || terminal {
			results = append(results, scenarioResult{id: id, status: status})
		}
	}
	if config.version == "2" {
		writeCountReport(t, suite, identity, results, config.strict)
	} else {
		writeReport(t, suite, identity, results)
	}
}

// ---- the report ------------------------------------------------------------------------------

// What one scenario came to, in the words the report uses.
const (
	statusPassed  = "passed"
	statusFailed  = "failed"
	statusSkipped = "skipped"
)

// scenarioResult is one scenario's verdict, for the report.
type scenarioResult struct {
	id     string
	status string
}

// report is `ess-conformance-report/1`: the closed document a conformance run publishes, and the
// one `aep artifact evidence --from` reads. The same shape the Rust runner writes, so a workflow
// system adapting one adapts the other.
//
// The status vocabulary is the runner's: `passed` when every scenario passed, `failed` when any
// failed, and `inconclusive` when none failed and some were skipped — a skipped scenario is one
// the target could not answer, and a run that could not ask everything cannot say the
// specification held.
type report struct {
	Format          string   `json:"format"`
	Specification   string   `json:"specification"`
	SpecDigest      string   `json:"spec_digest"`
	Implementation  string   `json:"implementation"`
	Status          string   `json:"status"`
	ScenariosTotal  int      `json:"scenarios_total"`
	ScenariosFailed int      `json:"scenarios_failed"`
	SuiteVersion    string   `json:"suite_version"`
	FailedScenarios []string `json:"failed_scenarios"`
	CompletedAt     int64    `json:"completed_at"`
}

// writeReport writes the run's report where ESS_REPORT_OUT names, and nowhere when it is unset.
//
// An environment variable rather than a flag, because `go test` owns the flags and a generated
// package cannot add one without every adopter's test binary learning it. The clock is read here,
// once, at the edge: the one place in this file that knows what time it is.
func writeReport(t *testing.T, suite Suite, identity Identity, results []scenarioResult) {
	t.Helper()
	path := os.Getenv("ESS_REPORT_OUT")
	if path == "" {
		return
	}

	failed := make([]string, 0)
	anyFailed, anySkipped := false, false
	for _, result := range results {
		switch result.status {
		case statusPassed:
			continue
		case statusFailed:
			anyFailed = true
		case statusSkipped:
			anySkipped = true
		}
		failed = append(failed, result.status+" "+result.id)
	}
	status := statusPassed
	switch {
	case anyFailed:
		status = statusFailed
	case anySkipped:
		status = "inconclusive"
	}

	document := report{
		Format:          "ess-conformance-report/1",
		Specification:   suite.Provenance.System + "/" + suite.Provenance.SpecificationVersion,
		SpecDigest:      suite.Provenance.SpecDigest,
		Implementation:  identity.Name + " " + identity.Version,
		Status:          status,
		ScenariosTotal:  len(results),
		ScenariosFailed: len(failed),
		SuiteVersion:    suite.Provenance.SuiteVersion,
		FailedScenarios: failed,
		CompletedAt:     time.Now().UnixMilli(),
	}
	encoded, err := json.MarshalIndent(document, "", "  ")
	if err != nil {
		t.Errorf("the report does not encode, which is a runner defect: %v", err)
		return
	}
	if err := os.WriteFile(path, append(encoded, '\n'), 0o644); err != nil {
		t.Errorf("writing the report to %s: %v", path, err)
		return
	}
	t.Logf("report: %s, %d scenario(s), %d not passed, written to %s", status, len(results), len(failed), path)
}

// run is one scenario in flight, and everything it has bound.
type run struct {
	t           *testing.T
	target      Target
	harness     *Harness
	correlation string

	// instances are what `capture_instance` bound, by name.
	instances map[string]Node
	// marked are the instants `mark_instant` named, so a window measured from one nothing marked
	// is a suite defect rather than a measurement from whatever was in hand.
	marked map[string]bool
	// observed are the events the last command published, by event name. Cleared per command,
	// because every `expect_no_event` is a claim about *that* invocation.
	observed map[string][]ObservedEvent
	// seen are the events observed anywhere in this scenario so far, in the order they arrived.
	//
	// A second record rather than the same one, because the two answer different questions. A
	// negative event assertion asks what this command published; a value written `observed` asks
	// what some earlier step in this scenario published, which is what the suite means by it — and
	// a scenario that arranges further instances after the branch would otherwise lose the branch's
	// own occurrence the moment the next command ran.
	seen []ObservedEvent
	// last is what the most recent command did, for the assertions that read it.
	last CommandResult
	// consistency is the token the last command returned, for a read_your_writes query.
	consistency string
	// lastView is what the last query_view returned, for the expect_view after it.
	lastView ViewResult
	// queried is which view lastView came from.
	queried string
	// status is what this scenario has come to so far: passed until a step fails or skips.
	status string
	// callbacksComplete records returned callbacks, independently of a provisional skip/failure.
	// A Goexit or panic inside teardown cannot complete the earlier step's verdict.
	callbacksComplete bool
}

func (r *run) execute(id string, scenario Scenario) {
	context := ScenarioContext{Scenario: id, Correlation: r.correlation}
	if err := r.target.BeginScenario(context); err != nil {
		r.callbacksComplete = true // begin returned; no teardown is required
		if errors.Is(err, ErrUnsupported) {
			r.skip("the target does not support this scenario: %v", err)
		}
		r.status = statusFailed
		r.t.Fatalf("begin: %v", err)
	}
	defer func() {
		err := r.target.EndScenario(context)
		r.callbacksComplete = true
		if err != nil {
			r.status = statusFailed
			r.t.Errorf("end: %v", err)
		}
	}()

	if scenario.Purpose != "" {
		r.t.Log(scenario.Purpose)
	}
	for index, step := range scenario.Steps {
		if !r.step(index, step) {
			return
		}
	}
}

// step performs one step, reporting whether the scenario should continue.
//
// A failed assertion stops the scenario: the steps after it were written assuming this one held,
// and running them produces a second failure about the first one's cause.
func (r *run) step(index int, step Step) bool {
	switch step.Step {
	case "execute_command":
		return r.executeCommand(index, step)
	case "expect_outcome":
		return r.expectOutcome(index, step)
	case "expect_error":
		return r.expectError(index, step)
	case "expect_event":
		return r.expectEvent(index, step)
	case "expect_no_event":
		return r.expectNoEvent(index, step)
	case "eventually_event":
		return r.eventuallyEvent(index, step)
	case "capture_instance":
		return r.captureInstance(index, step)
	case "query_view":
		return r.queryView(index, step)
	case "expect_view":
		return r.expectView(index, step, false)
	case "eventually_view":
		return r.expectView(index, step, true)
	case "expect_invocation":
		return r.expectInvocation(index, step)
	case "redeliver_event":
		return r.redeliver(index, step)
	case "configure_external_outcome":
		return r.configure(index, step)
	case "mark_instant":
		return r.markInstant(index, step)
	case "expect_not_before":
		return r.expectElapsed(index, step, false)
	case "expect_within":
		return r.expectElapsed(index, step, true)
	case "expect_quiet":
		return r.expectQuiet(index, step)
	case "expect_halt":
		return r.expectHalt(index, step, false)
	case "eventually_halt":
		return r.expectHalt(index, step, true)
	default:
		// A step this build does not know is a suite written by a newer generator. Reporting it as
		// a failure would blame the implementation for the tool's age.
		r.skip("step %d is `%s`, which this generated runner does not implement", index, step.Step)
		return false
	}
}

func (r *run) executeCommand(index int, step Step) bool {
	input, ok := r.resolveAll(index, step.Input)
	if !ok {
		return false
	}
	result, err := r.target.ExecuteCommand(CommandRequest{
		Command:     step.Command,
		Actor:       step.Actor,
		Input:       input,
		Correlation: r.correlation,
	})
	if errors.Is(err, ErrUnsupported) {
		r.skip("step %d: the target does not expose `%s`", index, step.Command)
		return false
	}
	if err != nil {
		return r.fail(index, "executing `%s`: %v", step.Command, err)
	}
	r.consistency = result.Consistency
	r.last = result
	// Cleared, not accumulated. Every `expect_no_event` in a scenario is a claim about *this*
	// command — a scenario that creates an invoice and then pays it asserts that paying emitted no
	// `InvoiceCreated`, which would be false against everything seen so far.
	r.observed = map[string][]ObservedEvent{}
	for _, event := range result.DirectEvents {
		r.observed[event.Event] = append(r.observed[event.Event], event)
		r.remember(event)
	}
	return true
}

// remember records an occurrence for the whole scenario, without recording one twice.
func (r *run) remember(event ObservedEvent) {
	for _, held := range r.seen {
		if held.Event == event.Event && equal(held.Payload, event.Payload) {
			return
		}
	}
	r.seen = append(r.seen, event)
}

func (r *run) expectOutcome(index int, step Step) bool {
	if step.Outcome == nil {
		return r.fail(index, "the suite names no outcome, which is a generator defect")
	}
	if r.last.Outcome != step.Outcome.Outcome {
		return r.fail(
			index,
			"`%s` took `%s`, and the specification says `%s`",
			step.Outcome.Command, orNone(r.last.Outcome), step.Outcome.Outcome,
		)
	}
	return true
}

func (r *run) expectError(index int, step Step) bool {
	if r.last.Error != step.Error {
		return r.fail(index, "refused with `%s`, and the specification says `%s`", orNone(r.last.Error), step.Error)
	}
	return true
}

func (r *run) expectEvent(index int, step Step) bool {
	seen := r.observed[step.Event]
	if len(seen) == 0 {
		return r.fail(index, "`%s` was not emitted", step.Event)
	}
	var mismatch string
	for _, event := range seen {
		if !matches(event.Payload, step.Payload) {
			continue
		}
		// The declared fields, and what each holds. Asserting only that the event arrived would
		// pass an implementation that published it empty.
		if reason := holds(event.Payload, step.Shape); reason != "" {
			mismatch = reason
			continue
		}
		return true
	}
	if mismatch != "" {
		return r.fail(index, "`%s` was emitted, and %s", step.Event, mismatch)
	}
	return r.fail(
		index,
		"`%s` was emitted, and no instance of it carried %s",
		step.Event,
		describe(step.Payload),
	)
}

func (r *run) expectNoEvent(index int, step Step) bool {
	if len(r.observed[step.Event]) > 0 {
		return r.fail(index, "`%s` was emitted, and this branch does not emit it", step.Event)
	}
	return true
}

func (r *run) eventuallyEvent(index int, step Step) bool {
	deadline := r.harness.Deadline()
	for attempt := 0; attempt < deadline.Attempts; attempt++ {
		events, err := r.target.ObserveEvents(EventObservationRequest{
			Event:       step.Event,
			Correlation: r.correlation,
			Deadline:    Deadline{Attempts: deadline.Attempts - attempt},
		})
		if errors.Is(err, ErrUnsupported) {
			r.skip("step %d: the target cannot observe `%s`", index, step.Event)
			return false
		}
		if err != nil {
			return r.fail(index, "observing `%s`: %v", step.Event, err)
		}
		for _, event := range events {
			r.observed[event.Event] = append(r.observed[event.Event], event)
			r.remember(event)
		}
		if len(r.observed[step.Event]) > 0 {
			return true
		}
	}
	return r.fail(index, "`%s` was not observed within the run's budget", step.Event)
}

func (r *run) captureInstance(index int, step Step) bool {
	for _, event := range r.observed[step.Event] {
		if value, ok := event.Payload[step.Field]; ok {
			r.instances[step.Instance] = value
			return true
		}
	}
	return r.fail(
		index,
		"nothing bound `%s`: `%s` did not carry `%s`",
		step.Instance, step.Event, step.Field,
	)
}

func (r *run) queryView(index int, step Step) bool {
	params, ok := r.resolveAll(index, step.Params)
	if !ok {
		return false
	}
	result, err := r.target.QueryView(ViewRequest{
		View:        step.View,
		Params:      params,
		AtLeast:     r.consistency,
		Correlation: r.correlation,
		Deadline:    r.harness.Deadline(),
	})
	if errors.Is(err, ErrUnsupported) {
		r.skip("step %d: the target does not expose `%s`", index, step.View)
		return false
	}
	if err != nil {
		return r.fail(index, "querying `%s`: %v", step.View, err)
	}
	r.lastView = result
	r.queried = step.View
	return true
}

func (r *run) expectView(index int, step Step, retry bool) bool {
	attempts := 1
	if retry {
		attempts = r.harness.Deadline().Attempts
	}
	var last string
	for attempt := 0; attempt < attempts; attempt++ {
		if retry || r.queried != step.View {
			params, ok := r.resolveAll(index, step.Params)
			if !ok {
				return false
			}
			result, err := r.target.QueryView(ViewRequest{
				View:        step.View,
				Params:      params,
				Correlation: r.correlation,
				Deadline:    Deadline{Attempts: attempts - attempt},
			})
			if errors.Is(err, ErrUnsupported) {
				r.skip("step %d: the target does not expose `%s`", index, step.View)
				return false
			}
			if err != nil {
				return r.fail(index, "querying `%s`: %v", step.View, err)
			}
			r.lastView = result
			r.queried = step.View
		}
		held, reason, undecidable := r.decide(index, step)
		if undecidable {
			// Not retried, ever. A row that cannot answer the question is a defect in the
			// specification or in what the view publishes, and polling to the deadline reports it
			// as a timeout — the same defect in a slower, less legible costume.
			return r.fail(index, "%s", reason)
		}
		if held {
			return true
		}
		last = reason
	}
	return r.fail(index, "%s", last)
}

// decide answers whether the view expectation holds, why not, and whether it could be decided.
func (r *run) decide(index int, step Step) (bool, string, bool) {
	expectation := step.Expectation
	if expectation == nil {
		return false, "the suite names no expectation, which is a generator defect", true
	}
	switch expectation.Expect {
	case "contains", "excludes":
		want, ok := r.resolveAll(index, expectation.Fields)
		if !ok {
			return false, "a value the expectation names is not bound", true
		}
		found := false
		for _, row := range r.lastView.Rows {
			if matches(row, want) {
				found = true
				break
			}
		}
		if expectation.Expect == "excludes" {
			if found {
				return false, fmt.Sprintf("`%s` holds a row where %s, and it must not", step.View, describe(want)), false
			}
			return true, "", false
		}
		if !found {
			return false, fmt.Sprintf("`%s` holds no row where %s", step.View, describe(want)), false
		}
		return true, "", false
	case "satisfies":
		predicate, err := parsePredicate(expectation.Predicate)
		if err != nil {
			return false, fmt.Sprintf("the suite's predicate does not parse: %v", err), true
		}
		// "At least one row" is part of the assertion: every row of an empty view satisfies
		// everything, so a target that published nothing would otherwise pass.
		if len(r.lastView.Rows) == 0 {
			return false, fmt.Sprintf("`%s` holds no rows", step.View), false
		}
		for _, row := range r.lastView.Rows {
			switch predicate.evaluate(facts(row)) {
			case truthTrue:
			case truthFalse:
				return false, fmt.Sprintf("`%s` in %s", predicate, describeRow(row)), false
			default:
				return false, fmt.Sprintf(
					"`%s` cannot be decided against %s, which is a defect in the view or the specification",
					predicate, describeRow(row),
				), true
			}
		}
		return true, "", false
	case "counts":
		// A count and not a match: which rows they are is what `contains` asks, and asking both in
		// one assertion would report two different defects under one name.
		if expectation.AtLeast == nil && expectation.AtMost == nil {
			return false, "a count with neither `at_least` nor `at_most` requires nothing, which is a generator defect", true
		}
		held := len(r.lastView.Rows)
		if expectation.AtLeast != nil && held < *expectation.AtLeast {
			return false, fmt.Sprintf(
				"`%s` holds %d row(s) and the specification requires at least %d",
				step.View, held, *expectation.AtLeast,
			), false
		}
		if expectation.AtMost != nil && held > *expectation.AtMost {
			return false, fmt.Sprintf(
				"`%s` holds %d row(s) and the specification permits at most %d",
				step.View, held, *expectation.AtMost,
			), false
		}
		return true, "", false
	case "ranked":
		return ranked(step.View, expectation.OrderBy, r.lastView.Rows)
	case "at":
		// A position in an unordered view names a different row on every read, and calling whichever
		// one came back "the first" is a coin toss reported as a check.
		if len(expectation.OrderBy) == 0 {
			return false, fmt.Sprintf(
				"`%s` declares no order, so a position in it names no particular row",
				step.View,
			), true
		}
		if expectation.Position == nil {
			return false, "the suite names no position, which is a generator defect", true
		}
		want, ok := r.resolveAll(index, expectation.Fields)
		if !ok {
			return false, "a value the expectation names is not bound", true
		}
		held := len(r.lastView.Rows)
		at := expectation.Position.Index
		switch expectation.Position.Row {
		case "first":
			at = 0
		case "last":
			at = held - 1
		case "nth":
		default:
			return false, fmt.Sprintf(
				"`%s` is a position this generated runner does not implement", expectation.Position.Row,
			), true
		}
		if at < 0 || at >= held {
			return false, fmt.Sprintf("`%s` holds %d row(s)", step.View, held), false
		}
		if !matches(r.lastView.Rows[at], want) {
			return false, fmt.Sprintf(
				"row %d of `%s` is %s", at, step.View, describeRow(r.lastView.Rows[at]),
			), false
		}
		return true, "", false
	default:
		return false, fmt.Sprintf("`%s` is an expectation this generated runner does not implement", expectation.Expect), true
	}
}

func (r *run) expectInvocation(index int, step Step) bool {
	invocations, err := r.target.ObserveInvocations(InvocationObservationRequest{
		Binding:     step.Binding,
		Command:     step.Command,
		Correlation: r.correlation,
		Deadline:    r.harness.Deadline(),
	})
	if errors.Is(err, ErrUnsupported) {
		// The one method the model explicitly refuses to require. Unsupported is a fact about the
		// target, not a failure of the specification.
		r.skip("step %d: the target does not expose what `%s` invoked", index, step.Binding)
		return false
	}
	if err != nil {
		return r.fail(index, "observing `%s`: %v", step.Binding, err)
	}
	want, ok := r.resolveAll(index, step.Input)
	if !ok {
		return false
	}
	for _, invocation := range invocations {
		if invocation.Command == step.Command && matches(invocation.Input, want) {
			return true
		}
	}
	return r.fail(
		index,
		"`%s` did not invoke `%s` with %s",
		step.Binding, step.Command, describe(want),
	)
}

func (r *run) redeliver(index int, step Step) bool {
	err := r.target.RedeliverEvent(RedeliveryRequest{Event: step.Event, Correlation: r.correlation})
	if errors.Is(err, ErrUnsupported) {
		r.skip("step %d: the target cannot redeliver `%s`, so `at_least_once` is unchecked", index, step.Event)
		return false
	}
	if err != nil {
		return r.fail(index, "redelivering `%s`: %v", step.Event, err)
	}
	return true
}

func (r *run) configure(index int, step Step) bool {
	if step.Force == nil {
		return r.fail(index, "the suite names no outcome to force, which is a generator defect")
	}
	err := r.target.ConfigureExternalOutcome(ExternalOutcomeControl{
		Command:     step.Force.Command,
		Outcome:     step.Force.Outcome,
		Correlation: r.correlation,
	})
	if errors.Is(err, ErrUnsupported) {
		r.skip("step %d: the target cannot force `%s`", index, step.Force.Outcome)
		return false
	}
	if err != nil {
		return r.fail(index, "forcing `%s`: %v", step.Force.Outcome, err)
	}
	return true
}

// clock is the target's clock, or a report that it has none.
//
// One place, so every one of the four steps reaches the same answer and the skip reads the same.
func (r *run) clock(index int) (Clock, bool) {
	clock, ok := r.target.(Clock)
	if !ok {
		r.skip(
			"step %d claims a length of time, and this target implements no Clock, so the claim "+
				"cannot be checked. It is reported unanswered rather than satisfied.",
			index,
		)
	}
	return clock, ok
}

// markInstant names the instant a later claim measures from.
func (r *run) markInstant(index int, step Step) bool {
	clock, ok := r.clock(index)
	if !ok {
		return false
	}
	if err := clock.MarkInstant(InstantMark{Instant: step.Instant, Correlation: r.correlation}); err != nil {
		if errors.Is(err, ErrUnsupported) {
			r.skip("step %d: the target cannot mark the instant `%s`", index, step.Instant)
			return false
		}
		return r.fail(index, "marking the instant `%s`: %v", step.Instant, err)
	}
	r.marked[step.Instant] = true
	return true
}

// elapsed asks the clock to let a window close, and returns what it read.
func (r *run) elapsed(index int, step Step, hold int, watching string) (ElapsedObservation, bool) {
	clock, ok := r.clock(index)
	if !ok {
		return ElapsedObservation{}, false
	}
	if !r.marked[step.Instant] {
		return ElapsedObservation{}, r.fail(
			index,
			"the window opens at `%s`, and no earlier step marked it; this is a defect in the "+
				"suite rather than in the implementation",
			step.Instant,
		)
	}
	observed, err := clock.ObserveElapsed(ElapsedRequest{
		Instant:     step.Instant,
		Hold:        hold,
		Watching:    watching,
		Correlation: r.correlation,
	})
	if errors.Is(err, ErrUnsupported) {
		r.skip("step %d: the target cannot let time pass since `%s`", index, step.Instant)
		return ElapsedObservation{}, false
	}
	if err != nil {
		r.fail(index, "letting %ds pass since `%s`: %v", hold, step.Instant, err)
		return ElapsedObservation{}, false
	}
	return observed, true
}

// expectElapsed requires that a window of a stated length really passed, on one side or the other.
//
// `within` measures what already happened and holds nothing: holding first would guarantee the
// answer it is asking about. `not_before` is the hold, and the hold is the point — the twenty
// seconds of an experiment are twenty seconds of the system running, not a number in a document.
func (r *run) expectElapsed(index int, step Step, within bool) bool {
	hold := step.Elapsed
	if within {
		hold = 0
	}
	observed, ok := r.elapsed(index, step, hold, "")
	if !ok {
		return false
	}
	claimed := int64(step.Elapsed) * 1000
	if within && observed.ElapsedMillis > claimed {
		return r.fail(
			index,
			"no more than %ds may have passed since `%s`, and the target measured %dms",
			step.Elapsed, step.Instant, observed.ElapsedMillis,
		)
	}
	if !within && observed.ElapsedMillis < claimed {
		return r.fail(
			index,
			"at least %ds must have passed since `%s`, and the target measured %dms",
			step.Elapsed, step.Instant, observed.ElapsedMillis,
		)
	}
	return true
}

// expectQuiet requires that an event was not published anywhere inside a window.
//
// A different claim from `expect_no_event`, which is about the command before it. This is about a
// stretch of the scenario in which no command of its own runs.
func (r *run) expectQuiet(index int, step Step) bool {
	observed, ok := r.elapsed(index, step, step.Elapsed, step.Event)
	if !ok {
		return false
	}
	// The window has to have closed for the claim to be about the window the scenario wrote. A
	// target that answered early reported on a shorter one, and reading that as agreement is the
	// silent pass this step exists to rule out.
	if observed.ElapsedMillis < int64(step.Elapsed)*1000 {
		return r.fail(
			index,
			"the window of %ds after `%s` did not close: the target measured %dms, so what it "+
				"answered about is shorter than what the scenario claims",
			step.Elapsed, step.Instant, observed.ElapsedMillis,
		)
	}
	if observed.Published > 0 {
		return r.fail(
			index,
			"`%s` was published %d time(s) within %ds of `%s`",
			step.Event, observed.Published, step.Elapsed, step.Instant,
		)
	}
	return true
}

// expectHalt requires that a reader's stop stopped the producer of an ordered read.
//
// Two conditions and the claim needs both. The source must have produced exactly what the reader
// took — a target that read the whole listing and handed back a prefix produced more — and the read
// must have ended because the reader said stop, because a source that ran out first ended for its
// own reason and a listing of exactly the right length would otherwise be read as a halt.
func (r *run) expectHalt(index int, step Step, retry bool) bool {
	reader, ok := r.target.(OrderedReader)
	if !ok {
		r.skip(
			"step %d claims a reader stopped an ordered scan, and this target implements no "+
				"OrderedReader, so the claim cannot be checked. It is reported unanswered rather "+
				"than satisfied.",
			index,
		)
		return false
	}
	params, ok := r.resolveAll(index, step.Params)
	if !ok {
		return false
	}
	// `Current` for the eventual half, exactly as expectView reads it: demanding the token would
	// make the target block until the projection caught up, which is the lag the retry observes.
	atLeast := r.consistency
	attempts := 1
	if retry {
		atLeast = ""
		attempts = r.harness.Deadline().Attempts
	}
	var last string
	for attempt := 0; attempt < attempts; attempt++ {
		observed, err := reader.ScanView(ScanRequest{
			View:        step.View,
			Params:      params,
			StopAfter:   step.After,
			AtLeast:     atLeast,
			Correlation: r.correlation,
			Deadline:    Deadline{Attempts: attempts - attempt},
		})
		if errors.Is(err, ErrUnsupported) {
			r.skip("step %d: the target cannot read `%s` a row at a time", index, step.View)
			return false
		}
		if err != nil {
			return r.fail(index, "reading `%s` a row at a time: %v", step.View, err)
		}
		if observed.Halted && observed.Produced == step.After {
			return true
		}
		if observed.Halted {
			last = fmt.Sprintf(
				"the reader stopped, and the target produced %d row(s) to hand it %d",
				observed.Produced, step.After,
			)
		} else {
			last = fmt.Sprintf(
				"the read ended because the source ran out after %d row(s), not because the "+
					"reader stopped it",
				observed.Produced,
			)
		}
	}
	return r.fail(
		index,
		"reading `%s` must stop after %d row(s) because the reader did: %s",
		step.View, step.After, last,
	)
}

// fail records one failed assertion and stops the scenario.
func (r *run) fail(index int, format string, args ...any) bool {
	r.status = statusFailed
	r.t.Errorf("step %d: "+format, append([]any{index}, args...)...)
	return false
}

// skip ends the scenario as one the target could not answer, and records that it did.
//
// Every skip in this file goes through here so the report and the test log cannot disagree
// about what the scenario came to.
func (r *run) skip(format string, args ...any) {
	r.status = statusSkipped
	r.t.Skipf(format, args...)
}

// resolveAll resolves every value a step carries against what this run has bound.
func (r *run) resolveAll(index int, values map[string]Value) (map[string]Node, bool) {
	resolved := make(map[string]Node, len(values))
	for field, value := range values {
		node, err := r.resolve(value)
		if err != nil {
			r.fail(index, "`%s`: %v", field, err)
			return nil, false
		}
		resolved[field] = node
	}
	return resolved, true
}

func (r *run) resolve(value Value) (Node, error) {
	switch value.Kind {
	case "literal":
		return value.Value, nil
	case "instance":
		bound, ok := r.instances[value.Instance]
		if !ok {
			return nil, fmt.Errorf("nothing bound the instance `%s`", value.Instance)
		}
		return bound, nil
	case "observed":
		// The whole scenario, and the first occurrence in it. `observed` means "what an earlier
		// step in this scenario published", so a later command that published nothing of this name
		// does not unbind it, and a neighbouring instance arranged afterwards does not take it over.
		for _, event := range r.seen {
			if event.Event != value.Event {
				continue
			}
			if field, ok := event.Payload[value.Field]; ok {
				return field, nil
			}
		}
		return nil, fmt.Errorf("`%s` was not observed carrying `%s`", value.Event, value.Field)
	default:
		return nil, fmt.Errorf("`%s` is a value kind this generated runner does not implement", value.Kind)
	}
}

// ---- comparisons ------------------------------------------------------------------------------

// matches reports whether every wanted field is present and equal.
//
// A subset, not an equality: a row carries what the view projects, and a scenario names the fields
// that identify the instance it is about.
func matches(row map[string]Node, want map[string]Node) bool {
	for field, expected := range want {
		actual, ok := row[field]
		if !ok || !equal(actual, expected) {
			return false
		}
	}
	return true
}

// equal compares two specification values structurally.
func equal(left, right Node) bool {
	switch left := left.(type) {
	case nil:
		return right == nil
	case bool:
		other, ok := right.(bool)
		return ok && left == other
	case float64:
		other, ok := asNumber(right)
		return ok && left == other
	case string:
		other, ok := right.(string)
		return ok && left == other
	case []any:
		other, ok := right.([]any)
		if !ok || len(left) != len(other) {
			return false
		}
		for index := range left {
			if !equal(left[index], other[index]) {
				return false
			}
		}
		return true
	case map[string]any:
		other, ok := right.(map[string]any)
		if !ok || len(left) != len(other) {
			return false
		}
		for key, value := range left {
			if !equal(value, other[key]) {
				return false
			}
		}
		return true
	default:
		return false
	}
}

func asNumber(value Node) (float64, bool) {
	switch value := value.(type) {
	case float64:
		return value, true
	case int:
		return float64(value), true
	case int64:
		return float64(value), true
	case json.Number:
		parsed, err := value.Float64()
		return parsed, err == nil
	default:
		return 0, false
	}
}

// describe renders a field match for a diagnostic, in a stable order.
func describe(fields map[string]Node) string {
	return describeRow(fields)
}

func describeRow(row map[string]Node) string {
	keys := make([]string, 0, len(row))
	for key := range row {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	parts := make([]string, 0, len(keys))
	for _, key := range keys {
		parts = append(parts, fmt.Sprintf("%s = %s", key, render(row[key])))
	}
	return strings.Join(parts, ", ")
}

func render(value Node) string {
	switch value := value.(type) {
	case nil:
		return "null"
	case string:
		return strconv.Quote(value)
	case float64:
		return strconv.FormatFloat(value, 'f', -1, 64)
	case bool:
		return strconv.FormatBool(value)
	default:
		encoded, err := json.Marshal(value)
		if err != nil {
			return fmt.Sprintf("%v", value)
		}
		return string(encoded)
	}
}

// holds reports why a payload does not carry what the specification declared, or "" when it does.
//
// A shape path is dotted — `amount.currency` — because a declared field may itself be a struct, and
// what is checked is the leaf that actually holds a value.
func holds(payload map[string]Node, shape map[string]Held) string {
	paths := make([]string, 0, len(shape))
	for path := range shape {
		paths = append(paths, path)
	}
	sort.Strings(paths)

	for _, path := range paths {
		value, ok := lookup(payload, path)
		if !ok {
			return fmt.Sprintf("did not carry `%s`", path)
		}
		expected := shape[path]
		if expected.Holds != "primitive" {
			// Only primitives are checked. A list or a map is a shape this runner would have to
			// re-derive to compare, and re-deriving a decision the compiler already took is how two
			// answers to one question appear.
			continue
		}
		if reason := primitive(expected.Kind, value); reason != "" {
			return fmt.Sprintf("`%s` %s", path, reason)
		}
	}
	return ""
}

// lookup follows a dotted path into a payload.
func lookup(payload map[string]Node, path string) (Node, bool) {
	var current Node = payload
	for _, segment := range strings.Split(path, ".") {
		mapping, ok := current.(map[string]any)
		if !ok {
			return nil, false
		}
		current, ok = mapping[segment]
		if !ok {
			return nil, false
		}
	}
	return current, true
}

// primitive reports why a value is not of the declared kind, or "" when it is.
func primitive(kind string, value Node) string {
	switch kind {
	case "string", "uuid", "timestamp", "duration":
		if _, ok := value.(string); !ok {
			return fmt.Sprintf("holds %s and the specification declares a %s", render(value), kind)
		}
	case "integer", "decimal":
		if _, ok := asNumber(value); !ok {
			return fmt.Sprintf("holds %s and the specification declares a %s", render(value), kind)
		}
	case "boolean":
		if _, ok := value.(bool); !ok {
			return fmt.Sprintf("holds %s and the specification declares a boolean", render(value))
		}
	}
	return ""
}

// ---- ordering ---------------------------------------------------------------------------------

// ranked reports whether rows are in the declared order.
//
// Adjacent pairs, not a sort: re-sorting and comparing would ask whether these are the right rows,
// which they trivially are, and would pass a view that returned everything backwards.
//
// Fewer than two rows holds. There is no adjacent pair to be out of order, and demanding one would
// quietly make every ordering claim a non-emptiness claim as well.
func ranked(view string, orderBy []string, rows []Row) (bool, string, bool) {
	keys := make([][2]string, 0, len(orderBy))
	for _, written := range orderBy {
		parts := strings.Fields(written)
		if len(parts) == 0 {
			return false, "the suite writes an empty ranking key, which is a generator defect", true
		}
		direction := "asc"
		if len(parts) > 1 {
			direction = parts[1]
		}
		keys = append(keys, [2]string{parts[0], direction})
	}

	for index := 0; index+1 < len(rows); index++ {
		earlier, later := rows[index], rows[index+1]
		for _, key := range keys {
			left, hasLeft := earlier[key[0]]
			right, hasRight := later[key[0]]
			if !hasLeft || !hasRight {
				return false, fmt.Sprintf(
					"`%s` is ranked by `%s` and does not publish it, which is a defect in the view",
					view, key[0],
				), true
			}
			order, ok := compare(left, right)
			if !ok {
				return false, fmt.Sprintf(
					"`%s` holds values of two kinds in `%s`, which have no order between them",
					view, key[0],
				), true
			}
			if order == 0 {
				continue
			}
			wanted := -1
			if key[1] == "desc" || key[1] == "descending" {
				wanted = 1
			}
			if order == wanted {
				break
			}
			return false, fmt.Sprintf(
				"`%s` holds %s then %s, which is not `%s %s`",
				view, describeRow(earlier), describeRow(later), key[0], key[1],
			), false
		}
	}
	return true, "", false
}

// compare orders two row values, reporting false where nothing orders them.
func compare(left, right Node) (int, bool) {
	if leftNumber, ok := asNumber(left); ok {
		if rightNumber, ok := asNumber(right); ok {
			switch {
			case leftNumber < rightNumber:
				return -1, true
			case leftNumber > rightNumber:
				return 1, true
			default:
				return 0, true
			}
		}
		return 0, false
	}
	if leftText, ok := left.(string); ok {
		if rightText, ok := right.(string); ok {
			return strings.Compare(leftText, rightText), true
		}
		return 0, false
	}
	if leftBool, ok := left.(bool); ok {
		if rightBool, ok := right.(bool); ok {
			switch {
			case leftBool == rightBool:
				return 0, true
			case rightBool:
				return -1, true
			default:
				return 1, true
			}
		}
	}
	return 0, false
}

func orNone(value string) string {
	if value == "" {
		return "nothing"
	}
	return value
}

// ---- opt-in report/2 admission and production -------------------------------------------------

type reportConfig struct {
	version string
	strict  bool
}

func reportConfiguration() (reportConfig, error) {
	version, selected := os.LookupEnv("ESS_REPORT_FORMAT")
	if !selected {
		version = "1"
	}
	if version != "1" && version != "2" {
		return reportConfig{}, fmt.Errorf("ESS_REPORT_FORMAT must be 1 or 2")
	}
	strict, strictSet := os.LookupEnv("ESS_CONFORMANCE_STRICT")
	diagnostic, diagnosticSet := os.LookupEnv("ESS_CONFORMANCE_ALLOW_INCOMPLETE")
	if (strictSet && strict != "1") || (diagnosticSet && diagnostic != "1") {
		return reportConfig{}, fmt.Errorf("strictness controls accept only unset or 1")
	}
	if strictSet && diagnosticSet {
		return reportConfig{}, fmt.Errorf("strict and allow-incomplete conflict")
	}
	if strictSet && version != "2" {
		return reportConfig{}, fmt.Errorf("strict conformance requires explicit ESS_REPORT_FORMAT=2")
	}
	return reportConfig{version: version, strict: strictSet}, nil
}

// Decode keys before comparing them, retaining scalar spellings and refusing duplicate keys.
func strictJSON(raw string) (any, error) {
	if !utf8.ValidString(raw) {
		return nil, fmt.Errorf("input is not UTF-8")
	}
	if err := scalarStrings(raw); err != nil {
		return nil, err
	}
	d := json.NewDecoder(strings.NewReader(raw))
	d.UseNumber()
	value, err := jsonValue(d, 0)
	if err != nil {
		return nil, err
	}
	if _, err = d.Token(); err != io.EOF {
		return nil, fmt.Errorf("trailing JSON input")
	}
	return value, nil
}

// Go's standard decoder replaces lone UTF-16 surrogates; admission must refuse instead.
func scalarStrings(raw string) error {
	quoted := false
	for i := 0; i < len(raw); i++ {
		if raw[i] == '"' {
			quoted = !quoted
			continue
		}
		if !quoted || raw[i] != '\\' {
			continue
		}
		i++
		if i >= len(raw) {
			return fmt.Errorf("unfinished escape")
		}
		if raw[i] != 'u' {
			continue
		}
		if i+4 >= len(raw) {
			return fmt.Errorf("unfinished Unicode escape")
		}
		code, err := strconv.ParseUint(raw[i+1:i+5], 16, 16)
		if err != nil {
			return err
		}
		i += 4
		if code >= 0xdc00 && code <= 0xdfff {
			return fmt.Errorf("lone low surrogate")
		}
		if code >= 0xd800 && code <= 0xdbff {
			if i+6 >= len(raw) || raw[i+1:i+3] != `\u` {
				return fmt.Errorf("lone high surrogate")
			}
			low, err := strconv.ParseUint(raw[i+3:i+7], 16, 16)
			if err != nil || low < 0xdc00 || low > 0xdfff {
				return fmt.Errorf("invalid surrogate pair")
			}
			i += 6
		}
	}
	return nil
}

func jsonValue(d *json.Decoder, depth int) (any, error) {
	if depth > 128 {
		return nil, fmt.Errorf("JSON nesting exceeds 128")
	}
	token, err := d.Token()
	if err != nil {
		return nil, err
	}
	switch token {
	case json.Delim('{'):
		result := map[string]any{}
		for d.More() {
			key, err := d.Token()
			if err != nil {
				return nil, err
			}
			name, ok := key.(string)
			if !ok {
				return nil, fmt.Errorf("object key is not a string")
			}
			if _, ok := result[name]; ok {
				return nil, fmt.Errorf("duplicate key %q", name)
			}
			child, err := jsonValue(d, depth+1)
			if err != nil {
				return nil, err
			}
			result[name] = child
		}
		_, err = d.Token()
		return result, err
	case json.Delim('['):
		result := []any{}
		for d.More() {
			child, err := jsonValue(d, depth+1)
			if err != nil {
				return nil, err
			}
			result = append(result, child)
		}
		_, err = d.Token()
		return result, err
	default:
		return token, nil
	}
}
func closed(value any, required, optional string) (map[string]any, error) {
	object, ok := value.(map[string]any)
	if !ok {
		return nil, fmt.Errorf("expected object")
	}
	requiredKeys, optionalKeys := strings.Fields(required), strings.Fields(optional)
	allowed := map[string]bool{}
	for _, key := range requiredKeys {
		allowed[key] = true
		if _, ok := object[key]; !ok {
			return nil, fmt.Errorf("missing field %s", key)
		}
	}
	for _, key := range optionalKeys {
		allowed[key] = true
	}
	for key := range object {
		if !allowed[key] {
			return nil, fmt.Errorf("unknown field %s", key)
		}
	}
	return object, nil
}
func text(value any) (string, error) {
	if s, ok := value.(string); ok {
		return s, nil
	}
	return "", fmt.Errorf("expected string")
}
func array(value any) ([]any, error) {
	if a, ok := value.([]any); ok {
		return a, nil
	}
	return nil, fmt.Errorf("expected array")
}
func unsigned(value any) (uint64, error) {
	n, ok := value.(json.Number)
	if !ok {
		return 0, fmt.Errorf("unsigned integer token required")
	}
	raw := string(n)
	if raw == "" || (raw != "0" && (raw[0] < '1' || raw[0] > '9')) {
		return 0, fmt.Errorf("unsigned integer token required")
	}
	for _, r := range raw {
		if r < '0' || r > '9' {
			return 0, fmt.Errorf("unsigned integer token required")
		}
	}
	return strconv.ParseUint(raw, 10, 64)
}

var qualifiedName = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9_-]*(\.[A-Za-z][A-Za-z0-9_-]*)*$`)
var factPath = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9_-]*(\.[A-Za-z0-9_-]+)*$`)
var kebabName = regexp.MustCompile(`^[a-z][a-z0-9]*(-[a-z0-9]+)*$`)
var stateName = regexp.MustCompile(`^[A-Z][A-Za-z0-9]*$`)
var modelDigest = regexp.MustCompile(`^[a-f0-9]{64}$`)

func name(value any, kebab bool) error {
	s, err := text(value)
	if err != nil {
		return err
	}
	pattern := qualifiedName
	if kebab {
		pattern = kebabName
	}
	if !pattern.MatchString(s) {
		return fmt.Errorf("invalid name %q", s)
	}
	return nil
}
func scenarioIdentity(id string) error {
	p := strings.Split(id, "/")
	valid := false
	q := func(s string) bool { return qualifiedName.MatchString(s) }
	k := func(s string) bool { return kebabName.MatchString(s) }
	switch {
	case len(p) == 3 && p[1] == "outcome":
		valid = q(p[0]) && k(p[2])
	case len(p) == 3 && p[1] == "authored":
		valid = q(p[0]) && k(p[2])
	case len(p) == 3 && p[1] == "binding":
		valid = k(p[0]) && (p[2] == "delivery" || p[2] == "flow" || p[2] == "mapping" || p[2] == "on-failure")
	case len(p) == 5 && p[1] == "state" && (p[3] == "refuses" || p[3] == "accepts"):
		valid = q(p[0]) && stateName.MatchString(p[2]) && q(p[4])
	case len(p) == 6 && p[1] == "transition" && p[3] == "by":
		valid = q(p[0]) && q(p[2]) && !strings.Contains(p[2], ".") && q(p[4]) && k(p[5])
	case len(p) == 5 && p[1] == "invariant" && p[2] == "after":
		valid = q(p[0]) && q(p[3]) && k(p[4])
	case len(p) == 5 && p[1] == "invariant" && p[2] == "at":
		valid = q(p[0]) && q(p[3]) && p[4] != ""
	}
	if !valid {
		return fmt.Errorf("malformed scenario ID %q", id)
	}
	return nil
}
func admitSuite(raw string) (Suite, error) {
	return admitSuiteDocument(raw, false)
}
func admitSuiteDocument(raw string, explicit bool) (Suite, error) {
	var suite Suite
	value, err := strictJSON(raw)
	if err != nil {
		return suite, err
	}
	root, err := closed(value, "provenance scenarios", "coverage")
	if err != nil {
		return suite, err
	}
	p, err := closed(root["provenance"], "suite_version system specification_version spec_digest contract_digest", "component")
	if err != nil {
		return suite, err
	}
	version, err := text(p["suite_version"])
	if err != nil {
		return suite, err
	}
	major := 0
	switch version {
	case "ess-conformance/1":
		major = 1
	case "ess-conformance/2":
		major = 2
	case "ess-conformance/3":
		major = 3
	case "ess-conformance/4":
		major = 4
	case "ess-conformance/5":
		major = 5
	default:
		return suite, fmt.Errorf("unsupported suite version %q", version)
	}
	if _, present := root["coverage"]; present != (major == 5) {
		return suite, fmt.Errorf("coverage is required exactly for suite/5")
	}
	for _, key := range []string{"system", "specification_version", "spec_digest", "contract_digest"} {
		s, err := text(p[key])
		if err != nil {
			return suite, err
		}
		if strings.HasSuffix(key, "digest") && !modelDigest.MatchString(s) {
			return suite, fmt.Errorf("invalid digest")
		}
	}
	if c, ok := p["component"]; ok && c != nil {
		if _, err := text(c); err != nil {
			return suite, err
		}
	}
	scenarios, ok := root["scenarios"].(map[string]any)
	if !ok {
		return suite, fmt.Errorf("scenarios must be an object")
	}
	for id, scenario := range scenarios {
		if err := scenarioIdentity(id); err != nil {
			return suite, err
		}
		s, err := closed(scenario, "purpose steps source", "")
		if err != nil {
			return suite, err
		}
		purpose, err := text(s["purpose"])
		if err != nil {
			return suite, err
		}
		if strings.TrimSpace(purpose) == "" || utf8.RuneCountInString(purpose) > 200 {
			return suite, fmt.Errorf("invalid purpose")
		}
		for _, r := range purpose {
			if r < 32 || (r >= 127 && r <= 159) {
				return suite, fmt.Errorf("purpose contains control")
			}
		}
		steps, err := array(s["steps"])
		if err != nil {
			return suite, err
		}
		for _, step := range steps {
			if err := admitStep(step, major); err != nil {
				return suite, fmt.Errorf("%s: %w", id, err)
			}
		}
		sources, err := array(s["source"])
		if err != nil {
			return suite, err
		}
		for _, source := range sources {
			if err := admitReference(source); err != nil {
				return suite, err
			}
		}
	}
	if major == 5 {
		if err := admitCoverage(root); err != nil {
			return suite, err
		}
		c := root["coverage"].(map[string]any)
		filter := c["selection"].(map[string]any)["filter"].(map[string]any)
		if !explicit && filter["kind"] != "all" {
			return suite, fmt.Errorf("explicit suite requires complete input parents")
		}
	}
	suite.original, suite.document = raw, root
	if major == 5 {
		suite.coverage = root["coverage"].(map[string]any)
		// Original admission includes parents which will never execute. Retain their exact
		// unsigned metadata independently of the inherited target API's narrower int fields.
		suite.Provenance = Provenance{SuiteVersion: version, System: p["system"].(string),
			SpecificationVersion: p["specification_version"].(string), SpecDigest: p["spec_digest"].(string),
			ContractDigest: p["contract_digest"].(string)}
		suite.Scenarios = make(map[string]Scenario, len(scenarios))
		for id, value := range scenarios {
			suite.Scenarios[id] = Scenario{Purpose: value.(map[string]any)["purpose"].(string)}
		}
		return suite, nil
	}
	err = json.Unmarshal([]byte(raw), &suite)
	return suite, err
}
func executionSuite(suite Suite) (Suite, error) {
	if suite.coverage != nil {
		if err := executionIntegers(suite.document["scenarios"].(map[string]any)); err != nil {
			return Suite{}, err
		}
		if err := json.Unmarshal([]byte(suite.original), &suite); err != nil {
			return Suite{}, fmt.Errorf("exact selected metadata exceeds the inherited Go execution view: %w", err)
		}
	}
	return suite, nil
}
func executionIntegers(scenarios map[string]any) error {
	maximum := uint64(^uint(0) >> 1)
	for _, id := range meaningKeys(scenarios) {
		for index, value := range scenarios[id].(map[string]any)["steps"].([]any) {
			step := value.(map[string]any)
			fields := map[string]any{}
			for _, field := range []string{"after", "elapsed"} {
				if value, present := step[field]; present {
					fields[field] = value
				}
			}
			if expectation, present := step["expectation"].(map[string]any); present {
				for _, field := range []string{"at_least", "at_most"} {
					if value := expectation[field]; value != nil {
						fields["expectation."+field] = value
					}
				}
				if position, present := expectation["position"].(map[string]any); present && position["row"] == "nth" {
					fields["expectation.position.index"] = position["index"]
				}
			}
			for _, field := range meaningKeys(fields) {
				value, err := unsigned(fields[field])
				if err != nil {
					return err
				}
				if value > maximum {
					return fmt.Errorf("scenario %s step %d field %s: exact value %d cannot be represented as Go int%d (maximum %d)", id, index, field, value, strconv.IntSize, maximum)
				}
			}
		}
	}
	return nil
}
func admitReference(value any) error {
	f, err := closed(value, "kind name", "")
	if err != nil {
		return err
	}
	kind, err := text(f["kind"])
	if err != nil {
		return err
	}
	switch kind {
	case "domain", "type", "entity", "command", "event", "error", "view", "actor":
		return name(f["name"], false)
	case "binding", "component":
		return name(f["name"], true)
	case "outcome":
		return admitOutcome(f["name"])
	case "transition":
		t, err := closed(f["name"], "entity transition", "")
		if err != nil {
			return err
		}
		if err := name(t["entity"], false); err != nil {
			return err
		}
		if err := name(t["transition"], false); err != nil {
			return err
		}
		if strings.Contains(t["transition"].(string), ".") {
			return fmt.Errorf("transition must be one name segment")
		}
		return nil
	default:
		return fmt.Errorf("unsupported semantic reference %s", kind)
	}
}
func admitOutcome(value any) error {
	f, err := closed(value, "command outcome", "")
	if err != nil {
		return err
	}
	if err := name(f["command"], false); err != nil {
		return err
	}
	return name(f["outcome"], true)
}
func admitValues(value any) error {
	values, ok := value.(map[string]any)
	if !ok {
		return fmt.Errorf("values must be an object")
	}
	for _, v := range values {
		f, ok := v.(map[string]any)
		if !ok {
			return fmt.Errorf("value must be an object")
		}
		kind, err := text(f["kind"])
		if err != nil {
			return err
		}
		switch kind {
		case "literal":
			if _, err := closed(v, "kind value", ""); err != nil {
				return err
			}
			if err := admitPayload(f["value"]); err != nil {
				return err
			}
		case "instance":
			if _, err := closed(v, "kind instance", ""); err != nil {
				return err
			}
			if err := name(f["instance"], true); err != nil {
				return err
			}
		case "observed":
			if _, err := closed(v, "kind event field", ""); err != nil {
				return err
			}
			if err := name(f["event"], false); err != nil {
				return err
			}
			if _, err := text(f["field"]); err != nil {
				return err
			}
		default:
			return fmt.Errorf("unsupported scenario value %s", kind)
		}
	}
	return nil
}
func admitPayload(value any) error {
	switch v := value.(type) {
	case json.Number:
		if _, err := strconv.ParseFloat(string(v), 64); err != nil {
			return fmt.Errorf("non-finite payload number: %w", err)
		}
	case []any:
		for _, item := range v {
			if err := admitPayload(item); err != nil {
				return err
			}
		}
	case map[string]any:
		for _, item := range v {
			if err := admitPayload(item); err != nil {
				return err
			}
		}
	}
	return nil
}
func admitShape(value any) error {
	object, ok := value.(map[string]any)
	if !ok {
		return fmt.Errorf("shape must be an object")
	}
	for _, v := range object {
		f, ok := v.(map[string]any)
		if !ok {
			return fmt.Errorf("shape leaf must be object")
		}
		kind, err := text(f["holds"])
		if err != nil {
			return err
		}
		required := "holds"
		switch kind {
		case "primitive":
			required += " kind"
		case "enum":
			required += " variants"
		case "list", "map", "union":
		default:
			return fmt.Errorf("unsupported holds")
		}
		if _, err := closed(v, required, "optional"); err != nil {
			return err
		}
		if optional, ok := f["optional"]; ok {
			if _, ok := optional.(bool); !ok {
				return fmt.Errorf("optional must be boolean")
			}
		}
		if kind == "primitive" {
			switch f["kind"] {
			case "string", "boolean", "integer", "decimal", "timestamp", "duration", "uuid", "bytes":
			default:
				return fmt.Errorf("unknown primitive")
			}
		}
		if kind == "enum" {
			variants, err := array(f["variants"])
			if err != nil {
				return err
			}
			for _, v := range variants {
				if _, err := text(v); err != nil {
					return err
				}
			}
		}
	}
	return nil
}
func admitExpectation(value any, major int) error {
	f, ok := value.(map[string]any)
	if !ok {
		return fmt.Errorf("expectation must be object")
	}
	tag, err := text(f["expect"])
	if err != nil {
		return err
	}
	if major < 2 && (tag == "counts" || tag == "at") {
		return fmt.Errorf("expectation requires suite/2")
	}
	required, optional := "expect", ""
	switch tag {
	case "contains", "excludes":
		required += " fields"
	case "satisfies":
		required += " predicate"
	case "ranked":
		required += " order_by"
	case "counts":
		optional = "at_least at_most"
	case "at":
		required += " order_by position"
		optional = "fields"
	default:
		return fmt.Errorf("unknown expectation %s", tag)
	}
	if _, err := closed(value, required, optional); err != nil {
		return err
	}
	if fields, ok := f["fields"]; ok {
		if err := admitValues(fields); err != nil {
			return err
		}
	}
	for _, key := range []string{"at_least", "at_most"} {
		if n, ok := f[key]; ok && n != nil {
			if _, err := unsigned(n); err != nil {
				return err
			}
		}
	}
	if order, ok := f["order_by"]; ok {
		ranks, err := array(order)
		if err != nil {
			return err
		}
		for _, rank := range ranks {
			s, err := text(rank)
			if err != nil {
				return err
			}
			words := strings.Fields(s)
			if len(words) < 1 || len(words) > 2 {
				return fmt.Errorf("invalid ranking")
			}
			if len(words) == 2 {
				switch words[1] {
				case "asc", "ascending", "desc", "descending":
				default:
					return fmt.Errorf("invalid ranking direction")
				}
			}
		}
	}
	if pos, ok := f["position"]; ok {
		p, ok := pos.(map[string]any)
		if !ok {
			return fmt.Errorf("invalid position")
		}
		switch p["row"] {
		case "first", "last":
			_, err = closed(pos, "row", "")
		case "nth":
			_, err = closed(pos, "row index", "")
			if err == nil {
				_, err = unsigned(p["index"])
			}
		default:
			err = fmt.Errorf("unknown position")
		}
		if err != nil {
			return err
		}
	}
	if predicate, ok := f["predicate"]; ok {
		if err := admitPayload(predicate); err != nil {
			return err
		}
		return admitPredicateEnvelope(predicate, 0)
	}
	return nil
}

// admitPredicateEnvelope mirrors Rust Predicate::from_node admission. The historical evaluator
// parses only at execution; its permissive leaf fallback is not an original-byte admission gate.
// Structured children and string `not` prefixes spend the same Rust depth budget.
func admitPredicateEnvelope(value any, depth int) error {
	if depth > 32 {
		return fmt.Errorf("predicate exceeds maximum depth 32")
	}
	switch node := value.(type) {
	case bool:
		return nil
	case string:
		if rest, ok := strings.CutPrefix(strings.TrimSpace(node), "not "); ok {
			return admitPredicateEnvelope(rest, depth+1)
		}
		return admitPredicateLeaf(node)
	case []any:
		for _, child := range node {
			if err := admitPredicateEnvelope(child, depth+1); err != nil {
				return err
			}
		}
	case map[string]any:
		for key, child := range node {
			switch key {
			case "all", "and", "all_of", "any", "or", "none", "none_of_these":
				if child == nil { // Rust Node::as_seq_or_single treats null as an empty list
					continue
				}
				children, ok := child.([]any)
				if !ok {
					children = []any{child}
				}
				for _, item := range children {
					if err := admitPredicateEnvelope(item, depth+1); err != nil {
						return err
					}
				}
			case "not":
				if err := admitPredicateEnvelope(child, depth+1); err != nil {
					return err
				}
			case "forall", "exists":
				fields, err := closed(child, "in as that", "")
				if err != nil {
					return err
				}
				over, err := text(fields["in"])
				if err != nil || !factPath.MatchString(over) {
					return fmt.Errorf("quantifier in must be a fact path")
				}
				bind, err := text(fields["as"])
				if err != nil || !factPath.MatchString(bind) || strings.Contains(bind, ".") {
					return fmt.Errorf("quantifier as must be one fact path segment")
				}
				if err := admitPredicateEnvelope(fields["that"], depth+1); err != nil {
					return err
				}
			default:
				if err := admitPredicatePath(key); err != nil {
					return err
				}
				if err := admitPredicateConstraint(child); err != nil {
					return err
				}
			}
		}
	default:
		return fmt.Errorf("predicate must be a boolean, expression, list or mapping")
	}
	return nil
}

func admitPredicatePath(path string) error {
	if !factPath.MatchString(path) {
		return fmt.Errorf("invalid predicate fact path %q", path)
	}
	return nil
}

func admitPredicateScalar(value any) error {
	switch value.(type) {
	case bool, string, json.Number:
		// Payload admission already checked finite numbers. Any string is legal: Rust operands
		// fall back to a literal when text (including a dotted spelling) is not a valid fact path.
		return nil
	default:
		return fmt.Errorf("predicate operand must be a boolean, number or string")
	}
}

func admitPredicateConstraint(value any) error {
	switch node := value.(type) {
	case []any:
		for _, item := range node {
			if err := admitPredicateScalar(item); err != nil {
				return err
			}
		}
	case map[string]any:
		// Every operator is checked; a known operator cannot hide a malformed neighbor.
		for operator, operand := range node {
			switch operator {
			case "eq", "equals", "==", "ne", "not_equals", "!=", "lt", "<", "le", "lte", "<=", "gt", ">", "ge", "gte", ">=":
				if err := admitPredicateScalar(operand); err != nil {
					return err
				}
			case "any_of", "in", "one_of", "none_of", "not_in":
				if operand == nil { // null is the empty sequence shorthand, not a null literal
					continue
				}
				items, ok := operand.([]any)
				if !ok {
					items = []any{operand}
				}
				for _, item := range items {
					if err := admitPredicateScalar(item); err != nil {
						return err
					}
				}
			case "exists", "defined":
				if _, ok := operand.(bool); !ok {
					return fmt.Errorf("predicate %s takes a boolean", operator)
				}
			case "truthy":
				// Rust's truthy form ignores its operand; payload validity still applies.
			default:
				return fmt.Errorf("unknown predicate constraint operator %q", operator)
			}
		}
	default:
		return admitPredicateScalar(value)
	}
	return nil
}

func admitPredicateLeaf(expression string) error {
	trimmed := strings.TrimSpace(expression)
	switch trimmed {
	case "always", "true", "never", "false":
		return nil
	}
	for _, function := range []string{"defined", "exists", "missing"} {
		if rest, ok := strings.CutPrefix(trimmed, function); ok {
			if rest, ok := strings.CutPrefix(strings.TrimSpace(rest), "("); ok {
				if path, ok := strings.CutSuffix(strings.TrimSpace(rest), ")"); ok {
					return admitPredicatePath(strings.TrimSpace(path))
				}
			}
		}
	}
	// Rust split_comparison chooses the first operator outside quotes, examining two-byte
	// operators before one-byte operators at that position. Its RHS is nonempty operand text.
	var quote byte
	for index := 0; index < len(trimmed); index++ {
		ch := trimmed[index]
		if quote != 0 {
			if ch == quote {
				quote = 0
			}
			continue
		}
		if ch == '\'' || ch == '"' {
			quote = ch
			continue
		}
		width := 0
		if index+1 < len(trimmed) {
			switch trimmed[index : index+2] {
			case "==", "!=", "<=", ">=":
				width = 2
			}
		}
		if width == 0 && (ch == '<' || ch == '>') {
			width = 1
		}
		if width != 0 {
			if err := admitPredicatePath(strings.TrimSpace(trimmed[:index])); err != nil {
				return err
			}
			if strings.TrimSpace(trimmed[index+width:]) == "" {
				return fmt.Errorf("predicate comparison requires a right operand")
			}
			return nil
		}
	}
	return admitPredicatePath(trimmed)
}

func admitStep(value any, major int) error {
	f, ok := value.(map[string]any)
	if !ok {
		return fmt.Errorf("step must be object")
	}
	tag, err := text(f["step"])
	if err != nil {
		return err
	}
	required, optional := "step", ""
	switch tag {
	case "configure_external_outcome":
		required += " force"
	case "execute_command":
		required += " command"
		optional = "actor input"
	case "expect_outcome":
		required += " outcome"
	case "expect_error":
		required += " error"
		optional = "fields"
	case "expect_event", "eventually_event":
		required += " event"
		optional = "payload shape"
	case "expect_no_event", "redeliver_event":
		required += " event"
	case "capture_instance":
		required += " instance entity event field"
	case "expect_invocation":
		required += " binding command"
		optional = "input"
	case "query_view":
		required += " view"
		optional = "params"
	case "expect_view":
		required += " view expectation"
	case "eventually_view":
		required += " view expectation"
		optional = "params"
	case "mark_instant":
		if major < 3 {
			return fmt.Errorf("step requires suite/3")
		}
		required += " instant"
	case "expect_not_before", "expect_within":
		if major < 3 {
			return fmt.Errorf("step requires suite/3")
		}
		required += " instant elapsed"
	case "expect_quiet":
		if major < 3 {
			return fmt.Errorf("step requires suite/3")
		}
		required += " event instant elapsed"
	case "expect_halt", "eventually_halt":
		if major < 4 {
			return fmt.Errorf("step requires suite/4")
		}
		required += " view after"
		optional = "params"
	default:
		return fmt.Errorf("unsupported step %s", tag)
	}
	if _, err := closed(value, required, optional); err != nil {
		return err
	}
	for key, v := range f {
		switch key {
		case "force", "outcome":
			err = admitOutcome(v)
		case "command", "entity", "event", "view", "error":
			err = name(v, false)
		case "actor":
			if v != nil {
				err = name(v, false)
			}
		case "binding", "instance", "instant":
			err = name(v, true)
		case "field":
			_, err = text(v)
		case "input", "params":
			err = admitValues(v)
		case "payload", "fields":
			if _, ok := v.(map[string]any); !ok {
				return fmt.Errorf("payload must be object")
			}
			err = admitPayload(v)
		case "shape":
			err = admitShape(v)
		case "expectation":
			err = admitExpectation(v, major)
		case "elapsed", "after":
			var n uint64
			n, err = unsigned(v)
			if err == nil && key == "elapsed" && n > 4294967295 {
				err = fmt.Errorf("elapsed exceeds u32")
			}
		}
		if err != nil {
			return err
		}
	}
	return nil
}

// The legacy clock remains signed; only report/2 uses this checked conversion seam.
var countReportNow = func() int64 { return time.Now().UnixMilli() }

func countDocument(suite Suite, identity Identity, results []scenarioResult, now int64) (map[string]any, error) {
	if !utf8.ValidString(identity.Name) || !utf8.ValidString(identity.Version) {
		return nil, fmt.Errorf("implementation identity is not UTF-8")
	}
	if now < 0 {
		return nil, fmt.Errorf("negative report/2 clock")
	}
	counts := map[string]uint64{"total": uint64(len(results)), "passed": 0, "failed": 0, "error": 0, "unsupported": 0, "skipped": 0}
	outcomes := map[string][]string{"passed": {}, "failed": {}, "error": {}, "unsupported": {}, "skipped": {}}
	seen := map[string]bool{}
	for _, result := range results {
		if seen[result.id] {
			return nil, fmt.Errorf("duplicate terminal result")
		}
		seen[result.id] = true
		if _, ok := suite.Scenarios[result.id]; !ok {
			return nil, fmt.Errorf("unexpected terminal result")
		}
		if result.status != statusPassed && result.status != statusFailed && result.status != statusSkipped {
			return nil, fmt.Errorf("unsupported Go terminal status")
		}
		if counts[result.status] == ^uint64(0) {
			return nil, fmt.Errorf("count overflow")
		}
		counts[result.status]++
		outcomes[result.status] = append(outcomes[result.status], result.id)
	}
	if len(seen) != len(suite.Scenarios) {
		return nil, fmt.Errorf("incomplete execution: selected subtests omitted or did not terminate")
	}
	for _, ids := range outcomes {
		sort.Strings(ids)
	}
	execution := "passed"
	if counts["failed"] > 0 {
		execution = "failed"
	} else if counts["skipped"] > 0 {
		execution = "inconclusive"
	}
	conformance := "inconclusive"
	if execution == "failed" {
		conformance = "failed"
	} else if execution == "passed" && counts["total"] > 0 && completeCoverage(suite.coverage) {
		conformance = "passed"
	}
	digest := sha256.Sum256([]byte(suite.original))
	coverage := map[string]any{"knowledge": "unknown"}
	if suite.coverage != nil {
		coverage = map[string]any{}
		for _, key := range []string{"knowledge", "selection", "counts", "refused"} {
			coverage[key] = suite.coverage[key]
		}
	}
	return map[string]any{
		"format": "ess-conformance-report/2", "specification": suite.Provenance.System + "/" + suite.Provenance.SpecificationVersion, "spec_digest": suite.Provenance.SpecDigest, "implementation": identity.Name + " " + identity.Version,
		"producer_profile": "go-scenario-status/1", "suite": map[string]any{"version": suite.Provenance.SuiteVersion, "digest_profile": "sha256-json-bytes/1", "digest": fmt.Sprintf("sha256:%x", digest)},
		"execution_status": execution, "conformance_status": conformance, "counts": counts, "outcomes": outcomes, "coverage": coverage, "policy": "complete-selection/1", "completed_at": uint64(now),
	}, nil
}
func writeCountReport(t *testing.T, suite Suite, identity Identity, results []scenarioResult, strict bool) {
	t.Helper()
	document, err := countDocument(suite, identity, results, countReportNow())
	if err != nil {
		t.Errorf("report/2 refused: %v", err)
		return
	}
	encoded, err := countCanonical(document)
	if err != nil {
		t.Errorf("report/2 encoding: %v", err)
		return
	}
	if path := os.Getenv("ESS_REPORT_OUT"); path != "" {
		if err := os.WriteFile(path, encoded, 0o644); err != nil {
			t.Errorf("writing report/2: %v", err)
			return
		}
	}
	if strict && document["conformance_status"] != "passed" {
		t.Errorf("strict conformance: %s (legacy suite coverage is unknown)", document["conformance_status"])
	}
}

// Canonical report/2 contains only unsigned integer scalars; JSON Number avoids binary64 loss.
func countCanonical(document any) ([]byte, error) {
	raw, err := json.Marshal(document)
	if err != nil {
		return nil, err
	}
	value, err := strictJSON(string(raw))
	if err != nil {
		return nil, err
	}
	var out bytes.Buffer
	var write func(any, int) error
	quote := func(s string) {
		out.WriteByte('"')
		for _, r := range s {
			switch r {
			case '"', '\\':
				out.WriteByte('\\')
				out.WriteRune(r)
			case '\n':
				out.WriteString(`\n`)
			case '\r':
				out.WriteString(`\r`)
			case '\t':
				out.WriteString(`\t`)
			case '\b':
				out.WriteString(`\b`)
			case '\f':
				out.WriteString(`\f`)
			default:
				if r < 32 {
					fmt.Fprintf(&out, `\u%04x`, r)
				} else {
					out.WriteRune(r)
				}
			}
		}
		out.WriteByte('"')
	}
	write = func(value any, depth int) error {
		indent := func(d int) { out.WriteString(strings.Repeat("  ", d)) }
		switch v := value.(type) {
		case nil:
			out.WriteString("null")
		case map[string]any:
			keys := make([]string, 0, len(v))
			for k := range v {
				keys = append(keys, k)
			}
			sort.Strings(keys)
			out.WriteByte('{')
			if len(keys) > 0 {
				out.WriteByte('\n')
			}
			for i, k := range keys {
				indent(depth + 1)
				quote(k)
				out.WriteString(": ")
				if err := write(v[k], depth+1); err != nil {
					return err
				}
				if i < len(keys)-1 {
					out.WriteByte(',')
				}
				out.WriteByte('\n')
			}
			if len(keys) > 0 {
				indent(depth)
			}
			out.WriteByte('}')
		case []any:
			out.WriteByte('[')
			if len(v) > 0 {
				out.WriteByte('\n')
			}
			for i, item := range v {
				indent(depth + 1)
				if err := write(item, depth+1); err != nil {
					return err
				}
				if i < len(v)-1 {
					out.WriteByte(',')
				}
				out.WriteByte('\n')
			}
			if len(v) > 0 {
				indent(depth)
			}
			out.WriteByte(']')
		case string:
			quote(v)
		case json.Number:
			if _, err := unsigned(v); err != nil {
				return err
			}
			out.WriteString(string(v))
		default:
			return fmt.Errorf("unexpected report scalar")
		}
		return nil
	}
	if err := write(value, 0); err != nil {
		return nil, err
	}
	out.WriteByte('\n')
	return out.Bytes(), nil
}
